/* DAWAH X — ahmad, অধ্যায় 47 · খণ্ড 47 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][47]=[[9201,9201,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَكْرَمُ النَّاسِ قَالَ أَتْقَاهُمْ قَالُوا لَيْسَ عَنْ هَذَا نَسْأَلُكَ قَالَ ‏ ‏فَيُوسُفُ ‏ ‏نَبِيُّ اللَّهِ ابْنُ نَبِيِّ اللَّهِ ابْنِ نَبِيِّ اللَّهِ ابْنِ خَلِيلِ اللَّهِ قَالُوا لَيْسَ عَنْ هَذَا نَسْأَلُكَ قَالَ فَعَنْ ‏ ‏مَعَادِنِ ‏ ‏الْعَرَبِ ‏ ‏تَسْأَلُونِي ‏ ‏خِيَارُهُمْ فِي الْجَاهِلِيَّةِ خِيَارُهُمْ فِي الْإِسْلَامِ إِذَا فَقُهُوا ‏","","",""],[9202,9202,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِيَّاكُمْ وَالظُّلْمَ فَإِنَّ الظُّلْمَ ظُلُمَاتٌ عِنْدَ اللَّهِ يَوْمَ الْقِيَامَةِ وَإِيَّاكُمْ ‏ ‏وَالْفُحْشَ ‏ ‏فَإِنَّ اللَّهَ لَا يُحِبُّ ‏ ‏الْفُحْشَ ‏ ‏وَالتَّفَحُّشَ ‏ ‏وَإِيَّاكُمْ ‏ ‏وَالشُّحَّ ‏ ‏فَإِنَّهُ دَعَا مَنْ قَبْلَكُمْ فَاسْتَحَلُّوا مَحَارِمَهُمْ وَسَفَكُوا دِمَاءَهُمْ وَقَطَّعُوا أَرْحَامَهُمْ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْأُمَوِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا زَنَتْ خَادِمُ أَحَدِكُمْ ‏ ‏فَذَكَرَ مَعْنَى الْحَدِيثِ ‏ ‏يَعْنِي ‏ ‏لِيَحْيَى بْنِ سَعِيدٍ الْقَطَّانِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى الْقَطَّانُ ‏ ‏عَنْ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِيَّاكُمْ وَالظُّلْمَ ‏ ‏وَذَكَرَ الْحَدِيثَ ‏","","",""],[9203,9203,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَلَمَةُ بْنُ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَجُلًا ‏ ‏تَقَاضَى ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعِيرًا فَقَالُوا مَا نَجِدُ إِلَّا أَفْضَلَ مِنْ ‏ ‏سِنِّهِ ‏ ‏فَقَالَ أَعْطُوهُ فَقَالَ أَوْفَيْتَنِي ‏ ‏أَوْفَى ‏ ‏اللَّهُ لَكَ قَالَ ‏ ‏خِيَارُ النَّاسِ أَحْسَنُهُمْ ‏ ‏قَضَاءً ‏","","",""],[9204,9204,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ وَسَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏قُلْتُ ‏ ‏لِيَحْيَى ‏ ‏كِلَاهُمَا عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ ‏ ‏قَالَ ‏ ‏مَا مِنْ أَمِيرِ عَشَرَةٍ إِلَّا يُؤْتَى بِهِ يَوْمَ الْقِيَامَةِ ‏ ‏مَغْلُولًا ‏ ‏لَا يَفُكُّهُ إِلَّا الْعَدْلُ أَوْ ‏ ‏يُوبِقُهُ ‏ ‏الْجَوْرُ ‏","","",""],[9205,9205,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏وَسَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏قُلْتُ ‏ ‏لِيَحْيَى ‏ ‏كِلَاهُمَا عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ ‏ ‏قَالَ ‏ ‏شُعْبَتَانِ مِنْ أَمْرِ الْجَاهِلِيَّةِ لَا يَتْرُكُهُمَا النَّاسُ أَبَدًا ‏ ‏النِّيَاحَةُ ‏ ‏وَالطَّعْنُ فِي النَّسَبِ ‏","","",""],[9206,9206,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْأَسْوَدُ بْنُ الْعَلَاءِ بْنِ جَارِيَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مِنْ حِينِ يَخْرُجُ أَحَدُكُمْ مِنْ بَيْتِهِ إِلَى مَسْجِدِهِ فَرِجْلٌ تَكْتُبُ حَسَنَةً وَأُخْرَى ‏ ‏تَمْحُو سَيِّئَةً ‏","","",""],[9207,9207,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَهْوَنُ أَهْلِ النَّارِ عَذَابًا عَلَيْهِ نَعْلَانِ يَغْلِي مِنْهُمَا دِمَاغُهُ ‏","","",""],[9208,9208,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ تَعْلَمُونَ مَا أَعْلَمُ لَضَحِكْتُمْ قَلِيلًا وَلَبَكَيْتُمْ كَثِيرًا ‏","","",""],[9209,9209,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خُثَيْمُ بْنُ عِرَاكٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ عَلَى الْمُسْلِمِ فِي فَرَسِهِ وَلَا مَمْلُوكِهِ ‏ ‏صَدَقَةٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أُسَامَةُ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏عَنْ ‏ ‏عِرَاكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[9210,9210,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدٌ ‏ ‏ح ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَا نِسَاءَ الْمُسْلِمَاتِ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏قَالَهَا ثَلَاثًا ‏ ‏لَا ‏ ‏تَحْقِرَنَّ ‏ ‏جَارَةٌ لِجَارَتِهَا وَلَوْ ‏ ‏فِرْسِنَ ‏ ‏شَاةٍ ‏","","",""],[9211,9211,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏سَمِعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَوْتَ صَبِيٍّ فِي الصَّلَاةِ فَخَفَّفَ الصَّلَاةَ ‏","","",""],[9212,9212,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏اقْتَطَعَ ‏ ‏شِبْرًا مِنْ الْأَرْضِ بِغَيْرِ حَقِّهِ ‏ ‏طُوِّقَهُ ‏ ‏يَوْمَ الْقِيَامَةِ إِلَى ‏ ‏سَبْعِ ‏ ‏أَرَضِينَ ‏","","",""],[9213,9213,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا جَلَسَ قَوْمٌ مَجْلِسًا فَلَمْ يَذْكُرُوا اللَّهَ فِيهِ إِلَّا كَانَ عَلَيْهِمْ ‏ ‏تِرَةً ‏ ‏وَمَا مِنْ رَجُلٍ مَشَى طَرِيقًا فَلَمْ يَذْكُرْ اللَّهَ عَزَّ وَجَلَّ إِلَّا كَانَ عَلَيْهِ ‏ ‏تِرَةً ‏ ‏وَمَا مِنْ رَجُلٍ ‏ ‏أَوَى ‏ ‏إِلَى فِرَاشِهِ فَلَمْ يَذْكُرْ اللَّهَ إِلَّا كَانَ عَلَيْهِ ‏ ‏تِرَةً ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏حَدَّثَنَاه ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ ‏ ‏مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏وَلَمْ يَقُلْ إِذَا ‏ ‏أَوَى ‏ ‏إِلَى فِرَاشِهِ ‏","","",""],[9214,9214,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْقَطَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعَتَيْنِ فِي بَيْعَةٍ وَعَنْ لِبْسَتَيْنِ أَنْ ‏ ‏يَشْتَمِلَ ‏ ‏أَحَدُكُمْ ‏ ‏الصَّمَّاءَ ‏ ‏فِي ثَوْبٍ وَاحِدٍ أَوْ ‏ ‏يَحْتَبِيَ ‏ ‏بِثَوْبٍ لَيْسَ بَيْنَهُ وَبَيْنَ السَّمَاءِ شَيْءٌ ‏","","",""],[9215,9215,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَوْفٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَالْحَسَنِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏التَّسْبِيحُ لِلرِّجَالِ وَالتَّصْفِيقُ لِلنِّسَاءِ ‏","","",""],[9216,9216,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تُنْكَحُ الْمَرْأَةُ عَلَى عَمَّتِهَا وَلَا عَلَى خَالَتِهَا ‏","","",""],[9217,9217,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ النِّسَاءِ خَيْرٌ قَالَ الَّتِي تَسُرُّهُ إِذَا نَظَرَ إِلَيْهَا وَتُطِيعُهُ إِذَا أَمَرَ وَلَا تُخَالِفُهُ فِيمَا يَكْرَهُ فِي نَفْسِهَا وَلَا فِي مَالِهِ ‏","","",""],[9218,9218,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا سَالَمْنَاهُنَّ مُنْذُ حَارَبْنَاهُنَّ مَنْ تَرَكَ شَيْئًا خَشْيَةً فَلَيْسَ مِنَّا ‏ ‏يَعْنِي الْحَيَّاتِ ‏","","",""],[9219,9219,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏أَوَى ‏ ‏أَحَدُكُمْ إِلَى فِرَاشِهِ فَلْيَنْفُضْ فِرَاشَهُ بِدَاخِلَةِ ‏ ‏إِزَارِهِ ‏ ‏وَلْيَتَوَسَّدْ يَمِينَهُ ثُمَّ لِيَقُلْ بِاسْمِكَ رَبِّ وَضَعْتُ جَنْبِي وَبِكَ أَرْفَعُهُ اللَّهُمَّ إِنْ أَمْسَكْتَهَا فَارْحَمْهَا وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا بِمَا حَفِظْتَ بِهِ عِبَادَكَ الصَّالِحِينَ ‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ وَهُوَ الْحَرَّانِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏أَوَى ‏ ‏أَحَدُكُمْ إِلَى فِرَاشِهِ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[9220,9220,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِالسِّوَاكِ مَعَ الْوُضُوءِ وَلَأَخَّرْتُ الْعِشَاءَ إِلَى ثُلُثِ اللَّيْلِ ‏ ‏أَوْ نِصْفِ اللَّيْلِ ‏ ‏فَإِذَا مَضَى ثُلُثُ اللَّيْلِ ‏ ‏أَوْ نِصْفُ اللَّيْلِ ‏ ‏نَزَلَ إِلَى السَّمَاءِ الدُّنْيَا جَلَّ وَعَزَّ فَقَالَ ‏ ‏هَلْ مِنْ سَائِلٍ فَأُعْطِيَهُ هَلْ مِنْ مُسْتَغْفِرٍ فَأَغْفِرَ لَهُ هَلْ مِنْ تَائِبٍ فَأَتُوبَ عَلَيْهِ هَلْ مِنْ دَاعٍ فَأُجِيبَهُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْلَا أَنْ أَشُقَّ فَذَكَرَ مَعْنَاهُ وَقَالَ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ يَنْزِلُ فِي كُلِّ لَيْلَةٍ إِلَى سَمَاءِ الدُّنْيَا وَقَالَ فِيهِ حَتَّى يَطْلُعَ الْفَجْرُ ‏","","",""],[9221,9221,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْقَاسِمُ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّاسُ تَبَعٌ ‏ ‏لِقُرَيْشٍ ‏ ‏فِي هَذَا الشَّأْنِ خِيَارُهُمْ أَتْبَاعٌ لِخِيَارِهِمْ وَشِرَارُهُمْ أَتْبَاعٌ لِشِرَارِهِمْ ‏","","",""],[9222,9222,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثَةٌ لَا يَنْظُرُ اللَّهُ ‏ ‏يَعْنِي إِلَيْهِمْ يَوْمَ الْقِيَامَةِ الْإِمَامُ الْكَذَّابُ وَالشَّيْخُ الزَّانِي وَالْعَامِلُ ‏ ‏الْمَزْهُوُّ ‏","","",""],[9223,9223,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلَا يُؤْذِيَنَّ جَارَهُ وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ ضَيْفَهُ وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَسْكُتْ ‏ ‏وَقَالَ ‏ ‏يَحْيَى ‏ ‏مَرَّةً أَوْ لِيَصْمُتْ ‏","","",""],[9224,9224,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَبُلْ أَحَدُكُمْ فِي الْمَاءِ الدَّائِمِ وَلَا يَغْتَسِلْ فِيهِ مِنْ الْجَنَابَةِ ‏","","",""],[9225,9225,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَمَّا خَلَقَ اللَّهُ الْخَلْقَ كَتَبَ بِيَدِهِ عَلَى نَفْسِهِ إِنَّ رَحْمَتِي تَغْلِبُ غَضَبِي ‏","","",""],[9226,9226,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَجْمَعُوا بَيْنَ اسْمِي وَكُنْيَتِي فَإِنِّي أَنَا ‏ ‏أَبُو الْقَاسِمِ ‏ ‏اللَّهُ عَزَّ وَجَلَّ يُعْطِي وَأَنَا أَقْسِمُ ‏","","",""],[9227,9227,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ إِذَا سَافَرَ قَالَ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ ‏ ‏وَعْثَاءِ ‏ ‏السَّفَرِ ‏ ‏وَكَآبَةِ ‏ ‏الْمُنْقَلَبِ ‏ ‏وَسُوءِ الْمَنْظَرِ فِي الْأَهْلِ وَالْمَالِ اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ وَالْخَلِيفَةُ فِي الْأَهْلِ اللَّهُمَّ اطْوِ لَنَا الْأَرْضَ وَهَوِّنْ عَلَيْنَا السَّفَرَ ‏","","",""],[9228,9228,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَغْلِبَنَّكُمْ أَهْلُ ‏ ‏الْبَادِيَةِ ‏ ‏عَلَى اسْمِ صَلَاتِكُمْ ‏","","",""],[9229,9229,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏صَالِحٌ ‏ ‏مَوْلَى ‏ ‏التَّوْأَمَةِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ غَسَّلَ مَيِّتًا فَلْيَغْتَسِلْ ‏","","",""],[9230,9230,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُمَيْدُ بْنُ هِلَالٍ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏جُرَيْجٌ ‏ ‏يَتَعَبَّدُ فِي ‏ ‏صَوْمَعَتِهِ ‏ ‏قَالَ فَأَتَتْهُ أُمُّهُ فَقَالَتْ يَا ‏ ‏جُرَيْجُ ‏ ‏أَنَا أُمُّكَ فَكَلِّمْنِي قَالَ وَكَانَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏يَصِفُ كَمَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصِفُهَا وَضَعَ يَدَهُ عَلَى حَاجِبِهِ الْأَيْمَنِ قَالَ فَصَادَفَتْهُ ‏ ‏يُصَلِّي فَقَالَ يَا رَبِّ أُمِّي وَصَلَاتِي فَاخْتَارَ صَلَاتَهُ فَرَجَعَتْ ثُمَّ أَتَتْهُ فَصَادَفَتْهُ ‏ ‏يُصَلِّي فَقَالَتْ يَا ‏ ‏جُرَيْجُ ‏ ‏أَنَا أُمُّكَ فَكَلِّمْنِي فَقَالَ يَا رَبِّ أُمِّي وَصَلَاتِي فَاخْتَارَ صَلَاتَهُ ثُمَّ أَتَتْهُ فَصَادَفَتْهُ ‏ ‏يُصَلِّي فَقَالَتْ يَا ‏ ‏جُرَيْجُ ‏ ‏أَنَا أُمُّكَ فَكَلِّمْنِي قَالَ يَا رَبِّ أُمِّي وَصَلَاتِي فَاخْتَارَ صَلَاتَهُ فَقَالَتْ اللَّهُمَّ إِنَّ هَذَا ‏ ‏جُرَيْجٌ ‏ ‏وَإِنَّهُ ابْنِي وَإِنِّي كَلَّمْتُهُ فَأَبَى أَنْ يُكَلِّمَنِي اللَّهُمَّ فَلَا تُمِتْهُ ‏ ‏حَتَّى تُرِيَهُ ‏ ‏الْمُومِسَاتِ ‏ ‏وَلَوْ دَعَتْ عَلَيْهِ أَنْ يُفْتَتَنَ لَافْتُتِنَ قَالَ وَكَانَ رَاعٍ يَأْوِي إِلَى دَيْرِهِ قَالَ فَخَرَجَتْ امْرَأَةٌ ‏ ‏فَوَقَعَ ‏ ‏عَلَيْهَا الرَّاعِي فَوَلَدَتْ غُلَامًا فَقِيلَ مِمَّنْ هَذَا فَقَالَتْ هُوَ مِنْ صَاحِبِ ‏ ‏الدَّيْرِ ‏ ‏فَأَقْبَلُوا بِفُؤُوسِهِمْ ‏ ‏وَمَسَاحِيهِمْ ‏ ‏وَأَقْبَلُوا إِلَى ‏ ‏الدَّيْرِ ‏ ‏فَنَادَوْهُ فَلَمْ يُكَلِّمْهُمْ فَأَخَذُوا يَهْدِمُونَ دَيْرَهُ فَنَزَلَ إِلَيْهِمْ فَقَالُوا سَلْ هَذِهِ الْمَرْأَةَ قَالَ أُرَاهُ تَبَسَّمَ قَالَ ثُمَّ مَسَحَ رَأْسَ الصَّبِيِّ فَقَالَ مَنْ أَبُوكَ قَالَ رَاعِي الضَّأْنِ فَقَالُوا يَا ‏ ‏جُرَيْجُ ‏ ‏نَبْنِي مَا هَدَمْنَا مِنْ دَيْرِكَ بِالذَّهَبِ وَالْفِضَّةِ قَالَ لَا وَلَكِنْ أَعِيدُوهُ تُرَابًا كَمَا كَانَ فَفَعَلُوا ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَانَ رَجُلٌ فِي ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏تَاجِرًا وَكَانَ يَنْقُصُ مَرَّةً وَيَزِيدُ أُخْرَى قَالَ مَا فِي هَذِهِ التِّجَارَةِ خَيْرٌ أَلْتَمِسُ تِجَارَةً هِيَ خَيْرٌ مِنْ هَذِهِ فَبَنَى ‏ ‏صَوْمَعَةً ‏ ‏وَتَرَهَّبَ فِيهَا وَكَانَ يُقَالُ لَهُ ‏ ‏جُرَيْجٌ ‏ ‏فَذَكَرَهُ نَحْوَهُ ‏","","",""],[9231,9231,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ عَجْلَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ضَرَبَ أَحَدُكُمْ فَلْيَجْتَنِبْ الْوَجْهَ وَلَا يَقُلْ قَبَّحَ اللَّهُ وَجْهَكَ وَوَجْهَ مَنْ أَشْبَهَ وَجْهَكَ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ خَلَقَ ‏ ‏آدَمَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏عَلَى صُورَتِهِ ‏","","",""],[9232,9232,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تُنْكَحُ ‏ ‏الْأَيِّمُ ‏ ‏حَتَّى ‏ ‏تُسْتَأْمَرَ ‏ ‏وَلَا تُنْكَحُ ‏ ‏الْبِكْرُ ‏ ‏حَتَّى تُسْتَأْذَنَ قِيلَ يَا رَسُولَ اللَّهِ وَكَيْفَ إِذْنُهَا قَالَ أَنْ تَسْكُتَ ‏","","",""],[9233,9233,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ثَلَاثُ دَعَوَاتٍ لَا شَكَّ فِيهِنَّ دَعْوَةُ الْمُسَافِرِ وَالْمَظْلُومِ وَدَعْوَةُ الْوَالِدِ عَلَى وَلَدِهِ ‏","","",""],[9234,9234,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏سَجَدَ فِي ‏ ‏إِذَا السَّمَاءُ انْشَقَّتْ ‏ ‏قُلْتُ تَسْجُدُ فِيهَا قَالَ إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَجَدَ فِيهَا ‏","","",""],[9235,9235,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏وَيَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏الْمَعْنَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ سَمْعَانَ ‏ ‏قَالَ ‏ ‏أَتَانَا ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فِي مَسْجِدِ ‏ ‏بَنِي زُرَيْقٍ ‏ ‏قَالَ ثَلَاثٌ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْمَلُ بِهِنَّ قَدْ تَرَكَهُنَّ النَّاسُ ‏ ‏كَانَ يَرْفَعُ يَدَيْهِ مَدًّا إِذَا دَخَلَ فِي الصَّلَاةِ وَيُكَبِّرُ كُلَّمَا رَكَعَ وَرَفَعَ وَالسُّكُوتُ قَبْلَ الْقِرَاءَةِ يَسْأَلُ اللَّهَ مِنْ فَضْلِهِ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏يَدْعُو وَيَسْأَلُ اللَّهَ مِنْ فَضْلِهِ ‏","","",""],[9236,9236,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلَّهِ مِائَةُ رَحْمَةٍ أَنْزَلَ مِنْهَا رَحْمَةً وَاحِدَةً بَيْنَ الْإِنْسِ وَالْجِنِّ ‏ ‏وَالْهَوَامِّ ‏ ‏فَبِهَا يَتَعَاطَفُونَ وَبِهَا يَتَرَاحَمُونَ وَبِهَا تَعْطِفُ الْوَحْشُ عَلَى أَوْلَادِهَا وَأَخَّرَ تِسْعَةً وَتِسْعِينَ إِلَى يَوْمِ الْقِيَامَةِ يَرْحَمُ بِهَا عِبَادَهُ ‏","","",""],[9237,9237,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏يَزِيدَ يَعْنِي ابْنَ كَيْسَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِعَمِّهِ ‏ ‏قُلْ لَا إِلَهَ إِلَّا اللَّهُ أَشْهَدْ لَكَ بِهَا يَوْمَ الْقِيَامَةِ قَالَ لَوْلَا أَنْ تُعَيِّرَنِي ‏ ‏قُرَيْشٌ ‏ ‏يَقُولُونَ إِنَّمَا حَمَلَهُ عَلَى ذَلِكَ ‏ ‏الْجَزَعُ ‏ ‏لَأَقْرَرْتُ بِهَا عَيْنَكَ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏إِنَّكَ لَا تَهْدِي مَنْ أَحْبَبْتَ ‏}","","",""],[9238,9238,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ كَيْسَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو حَازِمٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُشِيرُ بِأُصْبُعِهِ مِرَارًا وَالَّذِي نَفْسُ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏بِيَدِهِ ‏ ‏مَا شَبِعَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَهْلُهُ ثَلَاثَةَ أَيَّامٍ ‏ ‏تِبَاعًا ‏ ‏مِنْ خُبْزِ ‏ ‏حِنْطَةٍ ‏ ‏حَتَّى فَارَقَ الدُّنْيَا ‏","","",""],[9239,9239,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏يُورِدُ ‏ ‏الْمُمْرِضُ عَلَى ‏ ‏الْمُصِحِّ ‏ ‏وَقَالَ لَا ‏ ‏عَدْوَى ‏ ‏وَلَا ‏ ‏طِيَرَةَ ‏ ‏وَلَا ‏ ‏هَامَةَ ‏ ‏فَمَنْ أَعْدَى الْأَوَّلَ ‏","","",""],[9240,9240,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَطَاءٌ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْضَلُ ‏ ‏الصَّدَقَةِ ‏ ‏عَنْ ظَهْرِ غِنًى وَالْيَدُ الْعُلْيَا خَيْرٌ مِنْ الْيَدِ السُّفْلَى وَابْدَأْ بِمَنْ تَعُولُ ‏ ‏وَقَالَ ‏ ‏يَحْيَى ‏ ‏مَرَّةً لَا ‏ ‏صَدَقَةَ ‏ ‏إِلَّا مِنْ ‏ ‏ظَهْرِ غِنًى ‏","","",""],[9241,9241,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا وُضُوءَ إِلَّا مِنْ ‏ ‏حَدَثٍ ‏ ‏أَوْ رِيحٍ ‏","","",""],[9242,9242,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدٌ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ كَانَتْ ‏ ‏يَعْنِي عِنْدَهُ مَظْلَمَةٌ فِي مَالِهِ أَوْ عِرْضِهِ فَلْيَأْتِهِ فَلْيَسْتَحِلَّهَا مِنْهُ قَبْلَ أَنْ يُؤْخَذَ أَوْ تُؤْخَذَ وَلَيْسَ عِنْدَهُ دِينَارٌ وَلَا دِرْهَمٌ فَإِنْ كَانَتْ لَهُ حَسَنَاتٌ أُخِذَ مِنْ حَسَنَاتِهِ فَأُعْطِيَهَا هَذَا وَإِلَّا أُخِذَ مِنْ سَيِّئَاتِ هَذَا فَأُلْقِيَ عَلَيْهِ ‏","","",""],[9243,9243,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ الشَّهِيدِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏كُلُّ الصَّلَاةِ يُقْرَأُ فِيهَا ‏ ‏فَمَا أَسْمَعَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْمَعْنَاكُمْ وَمَا أَخْفَى عَلَيْنَا أَخْفَيْنَا عَلَيْكُمْ ‏","","",""],[9244,9244,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏وَرُبَّمَا ذَكَرَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَتَقَرَّبُ الْعَبْدُ إِلَيَّ شِبْرًا إِلَّا تَقَرَّبْتُ إِلَيْهِ ذِرَاعًا وَلَا يَتَقَرَّبُ إِلَيَّ ذِرَاعًا إِلَّا تَقَرَّبْتُ إِلَيْهِ ‏ ‏بَاعًا ‏ ‏أَوْ ‏ ‏بُوعًا ‏","","",""],[9245,9245,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِي يَطْعَنُ نَفْسَهُ إِنَّمَا يَطْعَنُهَا فِي النَّارِ وَالَّذِي يَتَقَحَّمُ فِيهَا يَتَقَحَّمُ فِي النَّارِ وَالَّذِي يَخْنُقُ نَفْسَهُ يَخْنُقُهَا فِي النَّارِ ‏","","",""],[9246,9246,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْنِي قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏أَنَا خَيْرُ الشُّرَكَاءِ مَنْ عَمِلَ لِي عَمَلًا أَشْرَكَ فِيهِ غَيْرِي فَأَنَا مِنْهُ بَرِيءٌ وَهُوَ لِلَّذِي أَشْرَكَ ‏","","",""],[9247,9247,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيَأْتِيَنَّ عَلَى النَّاسِ زَمَانٌ لَا ‏ ‏يُبَالِي ‏ ‏الْمَرْءُ بِمَا أَخَذَ مِنْ الْمَالِ بِحَلَالٍ أَوْ بِحَرَامٍ ‏","","",""],[9248,9248,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏وَيَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمُؤْمِنُ يَأْكُلُ فِي مِعًى وَاحِدٍ وَالْكَافِرُ يَأْكُلُ فِي سَبْعَةِ أَمْعَاءٍ ‏","","",""],[9249,9249,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اخْتَتَنَ ‏ ‏إِبْرَاهِيمُ ‏ ‏وَهُوَ ابْنُ ثَمَانِينَ ‏ ‏اخْتَتَنَ ‏ ‏بِالْقَدُومِ ‏","","",""],[9250,9250,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو حَيَّانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو زُرْعَةَ بْنُ عَمْرِو بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِلَحْمٍ فَدُفِعَ إِلَيْهِ الذِّرَاعُ وَكَانَتْ تُعْجِبُهُ ‏ ‏فَنَهَسَ ‏ ‏مِنْهَا ‏ ‏نَهْسَةً ‏ ‏ثُمَّ قَالَ ‏ ‏أَنَا سَيِّدُ النَّاسِ يَوْمَ الْقِيَامَةِ وَهَلْ تَدْرُونَ لِمَ ذَلِكَ يَجْمَعُ اللَّهُ عَزَّ وَجَلَّ الْأَوَّلِينَ وَالْآخِرِينَ فِي ‏ ‏صَعِيدٍ ‏ ‏وَاحِدٍ يُسْمِعُهُمْ الدَّاعِي ‏ ‏وَيَنْفُذُهُمْ ‏ ‏الْبَصَرُ ‏ ‏وَتَدْنُو ‏ ‏الشَّمْسُ فَيَبْلُغُ النَّاسَ مِنْ الْغَمِّ ‏ ‏وَالْكَرْبِ ‏ ‏مَا لَا يُطِيقُونَ وَلَا يَحْتَمِلُونَ فَيَقُولُ بَعْضُ النَّاسِ لِبَعْضٍ أَلَا تَرَوْنَ إِلَى مَا أَنْتُمْ فِيهِ أَلَا تَرَوْنَ إِلَى مَا قَدْ بَلَغَكُمْ أَلَا تَنْظُرُونَ مَنْ ‏ ‏يَشْفَعُ ‏ ‏لَكُمْ إِلَى رَبِّكُمْ عَزَّ وَجَلَّ فَيَقُولُ بَعْضُ النَّاسِ لِبَعْضٍ أَبُوكُمْ ‏ ‏آدَمُ ‏ ‏فَيَأْتُونَ ‏ ‏آدَمَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَقُولُونَ يَا ‏ ‏آدَمُ ‏ ‏أَنْتَ أَبُو الْبَشَرِ خَلَقَكَ اللَّهُ بِيَدِهِ وَنَفَخَ فِيكَ مِنْ رُوحِهِ وَأَمَرَ الْمَلَائِكَةَ فَسَجَدُوا لَكَ ‏ ‏فَاشْفَعْ ‏ ‏لَنَا إِلَى رَبِّكَ أَلَا ‏ ‏تَرَى إِلَى مَا نَحْنُ فِيهِ أَلَا ‏ ‏تَرَى مَا قَدْ بَلَغَنَا فَيَقُولُ ‏ ‏آدَمُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏إِنَّ رَبِّي عَزَّ وَجَلَّ قَدْ غَضِبَ الْيَوْمَ غَضَبًا لَمْ يَغْضَبْ قَبْلَهُ مِثْلَهُ وَلَنْ يَغْضَبَ بَعْدَهُ مِثْلَهُ وَإِنَّهُ نَهَانِي عَنْ الشَّجَرَةِ فَعَصَيْتُهُ نَفْسِي نَفْسِي نَفْسِي نَفْسِي نَفْسِي اذْهَبُوا إِلَى غَيْرِي اذْهَبُوا إِلَى ‏ ‏نُوحٍ ‏ ‏فَيَأْتُونَ ‏ ‏نُوحًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَقُولُونَ يَا ‏ ‏نُوحُ ‏ ‏أَنْتَ أَوَّلُ الرُّسُلِ إِلَى أَهْلِ الْأَرْضِ وَسَمَّاكَ اللَّهُ عَبْدًا شَكُورًا ‏ ‏فَاشْفَعْ ‏ ‏لَنَا إِلَى رَبِّكَ أَلَا ‏ ‏تَرَى إِلَى مَا نَحْنُ فِيهِ أَلَا ‏ ‏تَرَى مَا قَدْ بَلَغَنَا فَيَقُولُ ‏ ‏نُوحٌ ‏ ‏إِنَّ رَبِّي قَدْ غَضِبَ الْيَوْمَ غَضَبًا لَمْ يَغْضَبْ قَبْلَهُ مِثْلَهُ وَلَنْ يَغْضَبَ بَعْدَهُ مِثْلَهُ وَإِنَّهُ كَانَتْ لِي دَعْوَةٌ عَلَى قَوْمِي نَفْسِي نَفْسِي نَفْسِي نَفْسِي اذْهَبُوا إِلَى غَيْرِي اذْهَبُوا إِلَى ‏ ‏إِبْرَاهِيمَ ‏ ‏فَيَأْتُونَ ‏ ‏إِبْرَاهِيمَ ‏ ‏فَيَقُولُونَ ‏ ‏يَا ‏ ‏إِبْرَاهِيمُ ‏ ‏أَنْتَ نَبِيُّ اللَّهِ ‏ ‏وَخَلِيلُهُ ‏ ‏مِنْ أَهْلِ الْأَرْضِ ‏ ‏اشْفَعْ ‏ ‏لَنَا إِلَى رَبِّكَ أَلَا ‏ ‏تَرَى إِلَى مَا نَحْنُ فِيهِ أَلَا ‏ ‏تَرَى مَا قَدْ بَلَغَنَا فَيَقُولُ لَهُمْ ‏ ‏إِبْرَاهِيمُ ‏ ‏إِنَّ رَبِّي قَدْ غَضِبَ الْيَوْمَ غَضَبًا لَمْ يَغْضَبْ قَبْلَهُ مِثْلَهُ وَلَنْ يَغْضَبَ بَعْدَهُ مِثْلَهُ فَذَكَرَ كَذِبَاتِهِ نَفْسِي نَفْسِي نَفْسِي نَفْسِي اذْهَبُوا إِلَى غَيْرِي اذْهَبُوا إِلَى ‏ ‏مُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَيَأْتُونَ ‏ ‏مُوسَى ‏ ‏فَيَقُولُونَ يَا ‏ ‏مُوسَى ‏ ‏أَنْتَ رَسُولُ اللَّهِ ‏ ‏اصْطَفَاكَ ‏ ‏اللَّهُ بِرِسَالَاتِهِ وَبِتَكْلِيمِهِ عَلَى النَّاسِ ‏ ‏اشْفَعْ ‏ ‏لَنَا إِلَى رَبِّكَ أَلَا ‏ ‏تَرَى إِلَى مَا نَحْنُ فِيهِ أَلَا ‏ ‏تَرَى مَا قَدْ بَلَغَنَا فَيَقُولُ لَهُمْ ‏ ‏مُوسَى ‏ ‏إِنَّ رَبِّي قَدْ غَضِبَ الْيَوْمَ غَضَبًا لَمْ يَغْضَبْ قَبْلَهُ مِثْلَهُ وَلَنْ يَغْضَبَ بَعْدَهُ مِثْلَهُ وَإِنِّي قَتَلْتُ نَفْسًا لَمْ أُومَرْ بِقَتْلِهَا نَفْسِي نَفْسِي نَفْسِي نَفْسِي اذْهَبُوا إِلَى غَيْرِي اذْهَبُوا إِلَى ‏ ‏عِيسَى ‏ ‏فَيَأْتُونَ ‏ ‏عِيسَى ‏ ‏فَيَقُولُونَ يَا ‏ ‏عِيسَى ‏ ‏أَنْتَ رَسُولُ اللَّهِ وَكَلِمَتُهُ أَلْقَاهَا إِلَى ‏ ‏مَرْيَمَ ‏ ‏وَرُوحٌ مِنْهُ قَالَ هَكَذَا هُوَ وَكَلَّمْتَ النَّاسَ فِي الْمَهْدِ ‏ ‏فَاشْفَعْ ‏ ‏لَنَا إِلَى رَبِّكَ أَلَا ‏ ‏تَرَى إِلَى مَا نَحْنُ فِيهِ أَلَا ‏ ‏تَرَى مَا قَدْ بَلَغَنَا فَيَقُولُ لَهُمْ ‏ ‏عِيسَى ‏ ‏إِنَّ رَبِّي قَدْ غَضِبَ الْيَوْمَ غَضَبًا لَمْ يَغْضَبْ قَبْلَهُ مِثْلَهُ وَلَنْ يَغْضَبَ بَعْدَهُ مِثْلَهُ وَلَمْ يَذْكُرْ لَهُ ذَنْبًا اذْهَبُوا إِلَى غَيْرِي اذْهَبُوا إِلَى ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَأْتُونِي فَيَقُولُونَ يَا ‏ ‏مُحَمَّدُ ‏ ‏أَنْتَ رَسُولُ اللَّهِ وَخَاتَمُ الْأَنْبِيَاءِ غَفَرَ اللَّهُ لَكَ ذَنْبَكَ مَا تَقَدَّمَ مِنْهُ وَمَا تَأَخَّرَ ‏ ‏فَاشْفَعْ ‏ ‏لَنَا إِلَى رَبِّكَ أَلَا ‏ ‏تَرَى إِلَى مَا نَحْنُ فِيهِ أَلَا ‏ ‏تَرَى مَا قَدْ بَلَغَنَا فَأَقُومُ ‏ ‏فَآتِي تَحْتَ الْعَرْشِ فَأَقَعُ سَاجِدًا لِرَبِّي عَزَّ وَجَلَّ ثُمَّ يَفْتَحُ اللَّهُ عَلَيَّ وَيُلْهِمُنِي مِنْ مَحَامِدِهِ وَحُسْنِ الثَّنَاءِ عَلَيْهِ شَيْئًا لَمْ يَفْتَحْهُ عَلَى أَحَدٍ قَبْلِي فَيُقَالُ يَا ‏ ‏مُحَمَّدُ ‏ ‏ارْفَعْ رَأْسَكَ وَسَلْ ‏ ‏تُعْطَهْ ‏ ‏اشْفَعْ ‏ ‏تُشَفَّعْ ‏ ‏فَأَقُولُ يَا رَبِّ أُمَّتِي أُمَّتِي يَا رَبِّ أُمَّتِي أُمَّتِي يَا رَبِّ أُمَّتِي أُمَّتِي يَا رَبِّ فَيَقُولُ يَا ‏ ‏مُحَمَّدُ ‏ ‏أَدْخِلْ مِنْ أُمَّتِكَ مَنْ لَا حِسَابَ عَلَيْهِ مِنْ الْبَابِ الْأَيْمَنِ مِنْ أَبْوَابِ الْجَنَّةِ وَهُمْ شُرَكَاءُ النَّاسِ فِيمَا سِوَاهُ مِنْ الْأَبْوَابِ ثُمَّ قَالَ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ لَمَا بَيْنَ ‏ ‏مِصْرَاعَيْنِ ‏ ‏مِنْ ‏ ‏مَصَارِيعِ ‏ ‏الْجَنَّةِ كَمَا بَيْنَ ‏ ‏مَكَّةَ ‏ ‏وَهَجَرَ ‏ ‏أَوْ كَمَا بَيْنَ ‏ ‏مَكَّةَ ‏ ‏وَبُصْرَى ‏","","",""],[9251,9251,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَجُلًا شَتَمَ ‏ ‏أَبَا بَكْرٍ ‏ ‏وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَالِسٌ فَجَعَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْجَبُ وَيَتَبَسَّمُ فَلَمَّا أَكْثَرَ رَدَّ عَلَيْهِ بَعْضَ قَوْلِهِ فَغَضِبَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَامَ فَلَحِقَهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ كَانَ يَشْتُمُنِي وَأَنْتَ جَالِسٌ فَلَمَّا رَدَدْتُ عَلَيْهِ بَعْضَ قَوْلِهِ غَضِبْتَ وَقُمْتَ قَالَ إِنَّهُ كَانَ مَعَكَ مَلَكٌ يَرُدُّ عَنْكَ فَلَمَّا رَدَدْتَ عَلَيْهِ بَعْضَ قَوْلِهِ وَقَعَ الشَّيْطَانُ فَلَمْ أَكُنْ لِأَقْعُدَ مَعَ الشَّيْطَانِ ثُمَّ قَالَ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏ثَلَاثٌ كُلُّهُنَّ حَقٌّ مَا مِنْ عَبْدٍ ظُلِمَ ‏ ‏بِمَظْلَمَةٍ ‏ ‏فَيُغْضِي عَنْهَا لِلَّهِ عَزَّ وَجَلَّ إِلَّا أَعَزَّ اللَّهُ بِهَا نَصْرَهُ وَمَا فَتَحَ رَجُلٌ بَابَ عَطِيَّةٍ يُرِيدُ بِهَا ‏ ‏صِلَةً ‏ ‏إِلَّا زَادَهُ اللَّهُ بِهَا كَثْرَةً وَمَا فَتَحَ رَجُلٌ بَابَ مَسْأَلَةٍ يُرِيدُ بِهَا كَثْرَةً إِلَّا زَادَهُ اللَّهُ عَزَّ وَجَلَّ بِهَا قِلَّةً ‏","","",""],[9252,9252,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏حَدَّثَنِي ‏ ‏وَهْبُ بْنُ كَيْسَانَ ‏ ‏قَالَ ‏ ‏مَرَّ أَبِي عَلَى ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏فَقَالَ أَيْنَ تُرِيدُ قَالَ غُنَيْمَةً لِي قَالَ نَعَمْ امْسَحْ ‏ ‏رُعَامَهَا ‏ ‏وَأَطِبْ ‏ ‏مُرَاحَهَا ‏ ‏وَصَلِّ فِي جَانِبِ ‏ ‏مُرَاحِهَا ‏ ‏فَإِنَّهَا مِنْ دَوَابِّ الْجَنَّةِ وَأْنَسْ بِهَا فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّهَا أَرْضٌ قَلِيلَةُ الْمَطَرِ قَالَ ‏ ‏يَعْنِي ‏ ‏الْمَدِينَةَ ‏","","",""],[9253,9253,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَلْمُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَكْرَهُ ‏ ‏الشِّكَالَ ‏ ‏مِنْ الْخَيْلِ ‏","","",""],[9254,9254,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْقَعْقَاعُ بْنُ حَكِيمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَحِمَ اللَّهُ رَجُلًا قَامَ مِنْ اللَّيْلِ فَصَلَّى وَأَيْقَظَ أَهْلَهُ فَصَلَّتْ فَإِنْ أَبَتْ ‏ ‏نَضَحَ ‏ ‏فِي وَجْهِهَا الْمَاءَ وَرَحِمَ اللَّهُ امْرَأَةً قَامَتْ مِنْ اللَّيْلِ وَأَيْقَظَتْ زَوْجَهَا فَصَلَّى فَإِنْ أَبَى ‏ ‏نَضَحَتْ ‏ ‏فِي وَجْهِهِ الْمَاءَ ‏","","",""],[9255,9255,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏بَيْعِ الْحَصَاةِ ‏ ‏وَبَيْعِ الْغَرَرِ ‏","","",""],[9256,9256,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ثَابِتٌ الزُّرَقِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَسُبُّوا الرِّيحَ فَإِنَّهَا تَجِيءُ بِالرَّحْمَةِ وَالْعَذَابِ وَلَكِنْ سَلُوا اللَّهَ مِنْ خَيْرِهَا وَتَعَوَّذُوا مِنْ شَرِّهَا ‏","","",""],[9257,9257,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَحِلُّ لِامْرَأَةٍ تُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ تُسَافِرُ يَوْمًا إِلَّا مَعَ ذِي ‏ ‏مَحْرَمٍ ‏","","",""],[9258,9258,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ثَلَاثَةٌ كُلُّهُمْ حَقٌّ عَلَى اللَّهِ عَزَّ وَجَلَّ عَوْنُهُ الْمُجَاهِدُ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ وَالنَّاكِحُ لِيَسْتَعْفِفَ ‏ ‏وَالْمُكَاتَبُ ‏ ‏يُرِيدُ الْأَدَاءَ ‏","","",""],[9259,9259,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي عَرُوبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ آدَمَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْأَنْبِيَاءُ إِخْوَةٌ ‏ ‏لِعَلَّاتٍ ‏ ‏دِينُهُمْ وَاحِدٌ ‏ ‏وَأُمَّهَاتُهُمْ شَتَّى وَأَنَا أَوْلَى النَّاسِ ‏ ‏بِعِيسَى ابْنِ مَرْيَمَ ‏ ‏لِأَنَّهُ لَمْ يَكُنْ بَيْنِي وَبَيْنَهُ نَبِيٌّ وَإِنَّهُ نَازِلٌ فَإِذَا رَأَيْتُمُوهُ فَاعْرِفُوهُ فَإِنَّهُ رَجُلٌ ‏ ‏مَرْبُوعٌ ‏ ‏إِلَى الْحُمْرَةِ وَالْبَيَاضِ ‏ ‏سَبْطٌ ‏ ‏كَأَنَّ رَأْسَهُ يَقْطُرُ وَإِنْ لَمْ يُصِبْهُ بَلَلٌ بَيْنَ ‏ ‏مُمَصَّرَتَيْنِ ‏ ‏فَيَكْسِرُ الصَّلِيبَ وَيَقْتُلُ الْخِنْزِيرَ وَيَضَعُ ‏ ‏الْجِزْيَةَ ‏ ‏وَيُعَطِّلُ الْمِلَلَ حَتَّى يُهْلِكَ اللَّهُ فِي زَمَانِهِ الْمِلَلَ كُلَّهَا غَيْرَ الْإِسْلَامِ وَيُهْلِكُ اللَّهُ فِي زَمَانِهِ ‏ ‏الْمَسِيحَ الدَّجَّالَ ‏ ‏الْكَذَّابَ وَتَقَعُ الْأَمَنَةُ فِي الْأَرْضِ حَتَّى ‏ ‏تَرْتَعَ ‏ ‏الْإِبِلُ مَعَ الْأُسْدِ جَمِيعًا وَالنُّمُورُ مَعَ الْبَقَرِ وَالذِّئَابُ مَعَ الْغَنَمِ وَيَلْعَبَ الصِّبْيَانُ وَالْغِلْمَانُ بِالْحَيَّاتِ لَا يَضُرُّ بَعْضُهُمْ بَعْضًا فَيَمْكُثُ مَا شَاءَ اللَّهُ أَنْ يَمْكُثَ ثُمَّ يُتَوَفَّى فَيُصَلِّيَ عَلَيْهِ الْمُسْلِمُونَ وَيَدْفِنُونَهُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ آدَمَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْأَنْبِيَاءُ فَذَكَرَ مَعْنَاهُ إِلَّا أَنَّهُ قَالَ حَتَّى يُهْلَكَ فِي زَمَانِهِ ‏ ‏مَسِيحُ الضَّلَالَةِ ‏ ‏الْأَعْوَرُ الْكَذَّابُ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏فِي تَفْسِيرِ ‏ ‏شَيْبَانَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ آدَمَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[9260,9260,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏دَخَلَ ‏ ‏رَجُلٌ ‏ ‏الْمَسْجِدَ فَصَلَّى ثُمَّ جَاءَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَلَّمَ فَرَدَّ عَلَيْهِ السَّلَامَ وَقَالَ ارْجِعْ فَصَلِّ فَإِنَّكَ لَمْ تُصَلِّ فَرَجَعَ فَفَعَلَ ذَلِكَ ثَلَاثَ مَرَّاتٍ قَالَ فَقَالَ وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا أُحْسِنُ غَيْرَ هَذَا فَعَلِّمْنِي قَالَ ‏ ‏إِذَا قُمْتَ إِلَى الصَّلَاةِ فَكَبِّرْ ثُمَّ اقْرَأْ مَا تَيَسَّرَ مَعَكَ مِنْ الْقُرْآنِ ثُمَّ ارْكَعْ حَتَّى تَطْمَئِنَّ رَاكِعًا ثُمَّ ارْفَعْ حَتَّى تَعْتَدِلَ قَائِمًا ثُمَّ اسْجُدْ حَتَّى تَطْمَئِنَّ سَاجِدًا ثُمَّ ارْفَعْ حَتَّى تَطْمَئِنَّ جَالِسًا ثُمَّ افْعَلْ ذَلِكَ فِي صَلَاتِكَ كُلِّهَا ‏","","",""],[9261,9261,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ يَعْنِي ابْنَ أَبِي خَالِدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زِيَادٌ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏كِسْرَى ‏ ‏بَعْدَ ‏ ‏كِسْرَى ‏ ‏وَلَا ‏ ‏قَيْصَرَ ‏ ‏بَعْدَ ‏ ‏قَيْصَرَ ‏ ‏وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ لَتُنْفَقَنَّ كُنُوزُهُمَا فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[9262,9262,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏وَيَزِيدُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏كَانَ ‏ ‏يُصَلِّي بِهِمْ ‏ ‏بِالْمَدِينَةِ ‏ ‏نَحْوًا مِنْ صَلَاةِ ‏ ‏قَيْسٍ ‏ ‏وَكَانَ ‏ ‏قَيْسٌ ‏ ‏لَا يُطَوِّلُ قَالَ قُلْتُ هَكَذَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي قَالَ نَعَمْ أَوْ ‏ ‏أَوْجَزُ ‏ ‏وَقَالَ ‏ ‏يَزِيدُ ‏ ‏وَأَوْجَزُ ‏ ‏حَدَّثَنَاه ‏ ‏وَكِيعٌ ‏ ‏قَالَ نَعَمْ ‏ ‏وَأَوْجَزُ ‏","","",""],[9263,9263,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَشْعَثَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ذَكْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَأَبِي سَعِيدٍ ‏ ‏وَجَابِرٍ ‏ ‏أَوْ اثْنَيْنِ مِنْ هَؤُلَاءِ الثَّلَاثَةِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الصَّرْفِ ‏","","",""],[9264,9264,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏فُضَيْلُ بْنُ غَزْوَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ أَبِي نُعْمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الذَّهَبُ بِالذَّهَبِ وَالْفِضَّةُ بِالْفِضَّةِ ‏ ‏وَالْوَرِقُ ‏ ‏بِالْوَرِقِ ‏ ‏مِثْلًا بِمِثْلٍ يَدًا بِيَدٍ مَنْ زَادَ أَوْ ازْدَادَ فَقَدْ ‏ ‏أَرْبَى ‏","","",""],[9265,9265,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جُحَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ عَنْ كَسْبِ ‏ ‏الْإِمَاءِ ‏","","",""],[9266,9266,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏خُبَيْبِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا بَيْنَ بَيْتِي وَمِنْبَرِي رَوْضَةٌ مِنْ رِيَاضِ الْجَنَّةِ وَمِنْبَرِي عَلَى حَوْضِي ‏","","",""],[9267,9267,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُؤْمِنُ يَغَارُ وَاللَّهُ أَشَدُّ غَيْرًا ‏","","",""],[9268,9268,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا ‏ ‏عَفَا ‏ ‏رَجُلٌ إِلَّا زَادَهُ اللَّهُ بِهِ عِزًّا وَلَا نَقَصَتْ ‏ ‏صَدَقَةٌ ‏ ‏مِنْ مَالٍ وَلَا ‏ ‏عَفَا ‏ ‏رَجُلٌ قَطُّ إِلَّا زَادَهُ اللَّهُ عِزًّا ‏","","",""],[9269,9269,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا أَدُلُّكُمْ عَلَى مَا يَرْفَعُ اللَّهُ عَزَّ وَجَلَّ بِهِ الدَّرَجَاتِ وَيُكَفِّرُ بِهِ الْخَطَايَا كَثْرَةُ ‏ ‏الْخُطَا إِلَى الْمَسَاجِدِ وَانْتِظَارُ الصَّلَاةِ بَعْدَ الصَّلَاةِ ‏ ‏وَإِسْبَاغُ ‏ ‏الْوُضُوءِ عَلَى ‏ ‏الْمَكَارِهِ ‏","","",""],[9270,9270,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَمْنَعُوا ‏ ‏إِمَاءَ ‏ ‏اللَّهِ مَسَاجِدَ اللَّهِ وَلْيَخْرُجْنَ ‏ ‏تَفِلَاتٍ ‏","","",""],[9271,9271,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيِّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَعَى ‏ ‏لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّجَاشِيَّ ‏ ‏فِي الْيَوْمِ الَّذِي مَاتَ فِيهِ فَخَرَجَ إِلَى الْمُصَلَّى فَصَفَّ أَصْحَابُهُ خَلْفَهُ وَكَبَّرَ عَلَيْهِ أَرْبَعًا ‏","","",""],[9272,9272,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ الْغِنَى عَنْ كَثْرَةِ ‏ ‏الْعَرَضِ ‏ ‏وَلَكِنَّ الْغِنَى غِنَى النَّفْسِ ‏","","",""],[9273,9273,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏مَثَلُ الْمُجَاهِدِ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ مَثَلُ ‏ ‏الْقَانِتِ ‏ ‏الصَّائِمِ فِي بَيْتِهِ الَّذِي لَا ‏ ‏يَفْتُرُ ‏ ‏حَتَّى يَرْجِعَ بِمَا رَجَعَ مِنْ ‏ ‏غَنِيمَةٍ ‏ ‏أَوْ يَتَوَفَّاهُ اللَّهُ فَيُدْخِلَهُ الْجَنَّةَ ‏","","",""],[9274,9274,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى يَعْنِي ابْنَ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏قَالَ ثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ اللَّهُ تَعَالَى ‏ ‏أَعْدَدْتُ لِعِبَادِي الصَّالِحِينَ مَا لَا عَيْنٌ رَأَتْ وَلَا أُذُنٌ سَمِعَتْ وَلَا خَطَرَ عَلَى قَلْبِ بَشَرٍ فَاقْرَءُوا إِنْ شِئْتُمْ ‏ { ‏فَلَا تَعْلَمُ نَفْسٌ مَا أُخْفِيَ لَهُمْ مِنْ ‏ ‏قُرَّةِ ‏ ‏أَعْيُنٍ ‏} ‏وَقَالَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ فِي الْجَنَّةِ شَجَرَةً يَسِيرُ الرَّاكِبُ فِي ظِلِّهَا مِائَةَ عَامٍ مَا يَقْطَعُهَا فَاقْرَءُوا إِنْ شِئْتُمْ ‏ { ‏وَظِلٍّ مَمْدُودٍ ‏} ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَوْضِعُ سَوْطِ أَحَدِكُمْ فِي الْجَنَّةِ خَيْرٌ مِنْ الدُّنْيَا وَمَا فِيهَا وَقَرَأَ ‏ { ‏فَمَنْ زُحْزِحَ عَنْ النَّارِ وَأُدْخِلَ الْجَنَّةَ فَقَدْ فَازَ وَمَا الْحَيَاةُ الدُّنْيَا إِلَّا مَتَاعُ ‏ ‏الْغُرُورِ ‏ }","","",""],[9275,9275,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ ‏ ‏إِذَا كَبَّرَ الْإِمَامُ فَكَبِّرُوا وَإِذَا رَكَعَ فَارْكَعُوا وَإِذَا سَجَدَ فَاسْجُدُوا وَإِنْ صَلَّى جَالِسًا فَصَلُّوا جُلُوسًا ‏","","",""],[9276,9276,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّاسُ ‏ ‏مَعَادِنُ ‏ ‏فَخِيَارُهُمْ فِي الْجَاهِلِيَّةِ خِيَارُهُمْ فِي الْإِسْلَامِ إِذَا فَقُهُوا ‏","","",""],[9277,9277,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقَدَّمُوا الشَّهْرَ بِيَوْمٍ وَلَا يَوْمَيْنِ إِلَّا أَنْ يُوَافِقَ أَحَدُكُمْ صَوْمًا كَانَ يَصُومُهُ صُومُوا لِرُؤْيَتِهِ وَأَفْطِرُوا لِرُؤْيَتِهِ فَإِنْ ‏ ‏غُمَّ ‏ ‏عَلَيْكُمْ فَأَتِمُّوا ثَلَاثِينَ يَوْمًا ثُمَّ أَفْطِرُوا ‏","","",""],[9278,9278,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ ‏ ‏فِي الْجَنِينِ ‏ ‏غُرَّةٌ ‏ ‏عَبْدٌ أَوْ أَمَةٌ فَقَالَ الَّذِي قُضِيَ عَلَيْهِ أَيَعْقِلُ مَنْ لَا أَكَلَ وَلَا شَرِبَ وَلَا صَاحَ وَلَا ‏ ‏اسْتَهَلَّ ‏ ‏فَمِثْلُ ذَلِكَ ‏ ‏يُطَلُّ ‏ ‏فَقَالَ إِنَّ هَذَا الْقَوْلَ لَقَوْلُ شَاعِرٍ فِيهِ ‏ ‏غُرَّةٌ ‏ ‏عَبْدٌ أَوْ أَمَةٌ ‏","","",""],[9279,9279,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ ‏ ‏الرُّؤْيَا الصَّالِحَةُ يَرَاهَا الْمُسْلِمُ أَوْ تُرَى لَهُ جُزْءٌ مِنْ سِتَّةٍ وَأَرْبَعِينَ جُزْءًا مِنْ النُّبُوَّةِ ‏","","",""],[9280,9280,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَنَامُ عَيْنِي وَلَا يَنَامُ قَلْبِي ‏","","",""],[9281,9281,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قِيلَ يَا رَسُولَ اللَّهِ ‏ ‏أَيُّ النِّسَاءِ خَيْرٌ قَالَ الَّتِي تَسُرُّهُ إِذَا نَظَرَ وَتُطِيعُهُ إِذَا أَمَرَ وَلَا تُخَالِفُهُ فِيمَا يَكْرَهُ فِي نَفْسِهَا وَمَالِهِ ‏","","",""],[9282,9282,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَغْلِبَنَّكُمْ أَهْلُ ‏ ‏الْبَادِيَةِ ‏ ‏عَلَى اسْمِ صَلَاتِكُمْ ‏","","",""],[9283,9283,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَدْنَى أَهْلِ النَّارِ عَذَابًا رَجُلٌ يُجْعَلُ لَهُ نَعْلَانِ يَغْلِي مِنْهُمَا دِمَاغُهُ ‏","","",""],[9284,9284,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ ‏ ‏أُقَاتِلُ النَّاسَ حَتَّى يَقُولُوا لَا إِلَهَ إِلَّا اللَّهُ فَإِذَا قَالُوا لَا إِلَهَ إِلَّا اللَّهُ ‏ ‏عَصَمُوا ‏ ‏مِنِّي دِمَاءَهُمْ وَأَمْوَالَهُمْ إِلَّا ‏ ‏بِحَقِّهَا ‏","","",""],[9285,9285,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سُمَيٌّ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا عَطَسَ وَضَعَ ثَوْبَهُ ‏ ‏أَوْ يَدَهُ ‏ ‏عَلَى جَبْهَتِهِ وَخَفَضَ ‏ ‏أَوْ ‏ ‏غَضَّ ‏ ‏مِنْ صَوْتِهِ ‏","","",""],[9286,9286,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيِّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَعَى ‏ ‏لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّجَاشِيَّ ‏ ‏الْيَوْمَ الَّذِي مَاتَ فِيهِ فَخَرَجَ إِلَى الْمُصَلَّى فَصَفَّ أَصْحَابُهُ خَلْفَهُ فَكَبَّرَ عَلَيْهِ أَرْبَعًا ‏","","",""],[9287,9287,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا انْتَهَى أَحَدُكُمْ إِلَى الْمَجْلِسِ فَلْيُسَلِّمْ فَإِنْ بَدَا لَهُ أَنْ يَجْلِسَ فَلْيَجْلِسْ ثُمَّ إِنْ قَامَ وَالْقَوْمُ جُلُوسٌ فَلْيُسَلِّمْ فَلَيْسَتْ الْأُولَى بِأَحَقَّ مِنْ الْآخِرَةِ ‏","","",""],[9288,9288,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏خُبَيْبُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سَبْعَةٌ يُظِلُّهُمْ اللَّهُ فِي ظِلِّهِ يَوْمَ لَا ظِلَّ إِلَّا ظِلُّهُ الْإِمَامُ الْعَادِلُ وَشَابٌّ نَشَأَ بِعِبَادَةِ اللَّهِ وَرَجُلٌ قَلْبُهُ مُتَعَلِّقٌ بِالْمَسَاجِدِ وَرَجُلَانِ تَحَابَّا فِي اللَّهِ عَزَّ وَجَلَّ اجْتَمَعَا عَلَيْهِ وَتَفَرَّقَا عَلَيْهِ وَرَجُلٌ تَصَدَّقَ ‏ ‏بِصَدَقَةٍ ‏ ‏أَخْفَاهَا لَا تَعْلَمُ شِمَالُهُ مَا تُنْفِقُ يَمِينُهُ وَرَجُلٌ ذَكَرَ اللَّهَ خَالِيًا ‏ ‏فَفَاضَتْ ‏ ‏عَيْنَاهُ وَرَجُلٌ دَعَتْهُ ذَاتُ مَنْصِبٍ وَجَمَالٍ إِلَى نَفْسِهَا قَالَ أَنَا أَخَافُ اللَّهَ عَزَّ وَجَلَّ ‏","","",""],[9289,9289,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اللَّهُمَّ إِنِّي أُحَرِّجُ حَقَّ الضَّعِيفَيْنِ الْيَتِيمِ وَالْمَرْأَةِ ‏","","",""],[9290,9290,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الشِّغَارِ قَالَ وَالشِّغَارُ أَنْ يَقُولَ الرَّجُلُ زَوِّجْنِي ابْنَتَكَ وَأُزَوِّجُكَ ابْنَتِي أَوْ زَوِّجْنِي أُخْتَكَ وَأُزَوِّجُكَ أُخْتِي قَالَ وَنَهَى عَنْ ‏ ‏بَيْعِ الْغَرَرِ ‏ ‏وَعَنْ ‏ ‏الْحَصَاةِ ‏","","",""],[9291,9291,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ثَوْرٌ يَعْنِي ابْنَ يَزِيدَ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعَيْنُ ‏ ‏حَقٌّ وَيَحْضُرُ بِهَا الشَّيْطَانُ وَحَسَدُ ابْنِ ‏ ‏آدَمَ ‏","","",""],[9292,9292,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏غُفِرَ لِرَجُلٍ نَحَّى غُصْنَ شَوْكٍ عَنْ طَرِيقِ النَّاسِ ‏","","",""],[9293,9293,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ هَاشِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو صَالِحٍ ‏ ‏مَوْلَى ‏ ‏السَّعْدِيِّينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ رِجَالًا يَسْتَنْفِرُونَ عَشَائِرَهُمْ يَقُولُونَ الْخَيْرَ الْخَيْرَ ‏ ‏وَالْمَدِينَةُ ‏ ‏خَيْرٌ لَهُمْ لَوْ كَانُوا يَعْلَمُونَ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ لَا يَصْبِرُ عَلَى ‏ ‏لَأْوَائِهَا ‏ ‏وَشِدَّتِهَا ‏ ‏أَحَدٌ إِلَّا كُنْتُ لَهُ شَهِيدًا ‏ ‏أَوْ شَفِيعًا ‏ ‏يَوْمَ الْقِيَامَةِ وَالَّذِي نَفْسِي بِيَدِهِ إِنَّهَا ‏ ‏لَتَنْفِي ‏ ‏أَهْلَهَا كَمَا ‏ ‏يَنْفِي ‏ ‏الْكِيرُ ‏ ‏خَبَثَ ‏ ‏الْحَدِيدِ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ لَا يَخْرُجُ مِنْهَا أَحَدٌ رَاغِبًا عَنْهَا إِلَّا أَبْدَلَهَا اللَّهُ عَزَّ وَجَلَّ خَيْرًا مِنْهُ ‏","","",""],[9294,9294,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏وَوَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ الْأَشْجَعِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَعَا الرَّجُلُ امْرَأَتَهُ إِلَى فِرَاشِهِ فَأَبَتْ عَلَيْهِ فَبَاتَ وَهُوَ غَضْبَانُ لَعَنَتْهَا الْمَلَائِكَةُ حَتَّى يُصْبِحَ ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏عَلَيْهَا سَاخِطٌ ‏","","",""],[9295,9295,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو حَيَّانَ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏بِلَالُ ‏ ‏حَدِّثْنِي ‏ ‏بِأَرْجَى ‏ ‏عَمَلٍ عَمِلْتَهُ فِي الْإِسْلَامِ عِنْدَكَ مَنْفَعَةً فَإِنِّي ‏ ‏سَمِعْتُ اللَّيْلَةَ ‏ ‏خَشْفَ ‏ ‏نَعْلَيْكَ بَيْنَ يَدَيَّ فِي الْجَنَّةِ فَقَالَ ‏ ‏بِلَالٌ ‏ ‏مَا عَمِلْتُ عَمَلًا فِي الْإِسْلَامِ ‏ ‏أَرْجَى ‏ ‏عِنْدِي مَنْفَعَةً إِلَّا أَنِّي لَمْ أَتَطَهَّرْ طُهُورًا تَامًّا فِي سَاعَةٍ مِنْ لَيْلٍ أَوْ نَهَارٍ إِلَّا صَلَّيْتُ بِذَلِكَ الطُّهُورِ مَا كَتَبَ اللَّهُ لِي أَنْ أُصَلِّيَ ‏","","",""],[9296,9296,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَجَّاحٌ يَعْنِي ابْنَ دِينَارٍ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ إِيَاسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَسْعُودٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَعَهُ ‏ ‏حَسَنٌ ‏ ‏وَحُسَيْنٌ ‏ ‏هَذَا عَلَى ‏ ‏عَاتِقِهِ ‏ ‏وَهَذَا عَلَى ‏ ‏عَاتِقِهِ ‏ ‏وَهُوَ ‏ ‏يَلْثِمُ ‏ ‏هَذَا مَرَّةً ‏ ‏وَيَلْثِمُ ‏ ‏هَذَا مَرَّةً حَتَّى انْتَهَى إِلَيْنَا فَقَالَ لَهُ رَجُلٌ يَا رَسُولَ اللَّهِ إِنَّكَ تُحِبُّهُمَا فَقَالَ ‏ ‏مَنْ أَحَبَّهُمَا فَقَدْ أَحَبَّنِي وَمَنْ أَبْغَضَهُمَا فَقَدْ أَبْغَضَنِي ‏","","",""],[9297,9297,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏وَأَبُو أُسَامَةَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏خُبَيْبِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سَيْحَانُ ‏ ‏وَجَيْحَانُ وَالنِّيلُ وَالْفُرَاتُ وَكُلٌّ مِنْ أَنْهَارِ الْجَنَّةِ ‏ ‏قَالَ ‏ ‏أَبُو أُسَامَةَ ‏ ‏كُلٌّ مِنْ أَنْهَارِ الْجَنَّةِ ‏","","",""],[9298,9298,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي يَحْيَى ‏ ‏مَوْلَى ‏ ‏جَعْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ يَا رَسُولَ اللَّهِ إِنَّ فُلَانَةَ يُذْكَرُ مِنْ كَثْرَةِ صَلَاتِهَا وَصِيَامِهَا وَصَدَقَتِهَا غَيْرَ أَنَّهَا تُؤْذِي جِيرَانَهَا بِلِسَانِهَا قَالَ ‏ ‏هِيَ فِي النَّارِ قَالَ يَا رَسُولَ اللَّهِ فَإِنَّ فُلَانَةَ يُذْكَرُ مِنْ قِلَّةِ صِيَامِهَا وَصَدَقَتِهَا وَصَلَاتِهَا وَإِنَّهَا تَصَدَّقُ ‏ ‏بِالْأَثْوَارِ ‏ ‏مِنْ ‏ ‏الْأَقِطِ ‏ ‏وَلَا تُؤْذِي جِيرَانَهَا بِلِسَانِهَا قَالَ هِيَ فِي الْجَنَّةِ ‏","","",""],[9299,9299,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ يَزِيدَ بْنِ جَابِرٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ الْأَشْعَرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏عَادَ ‏ ‏مَرِيضًا وَمَعَهُ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏مِنْ ‏ ‏وَعْكٍ ‏ ‏كَانَ بِهِ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبْشِرْ إِنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ ‏ ‏نَارِي أُسَلِّطُهَا عَلَى عَبْدِي الْمُؤْمِنِ فِي الدُّنْيَا لِتَكُونَ حَظَّهُ مِنْ النَّارِ فِي الْآخِرَةِ ‏","","",""],[9300,9300,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْبَاطٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُطَرِّفٌ ‏ ‏عَنْ ‏ ‏أَبِي الْجَهْمِ ‏ ‏عَنْ ‏ ‏أَبِي زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ قَاعِدًا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَتْهُ امْرَأَةٌ فَقَالَتْ يَا رَسُولَ اللَّهِ طَوْقٌ مِنْ ذَهَبٍ قَالَ ‏ ‏طَوْقٌ مِنْ نَارٍ قَالَتْ يَا رَسُولَ اللَّهِ سِوَارَانِ مِنْ ذَهَبٍ قَالَ سِوَارَانِ مِنْ نَارٍ قَالَتْ ‏ ‏قُرْطَانِ ‏ ‏مِنْ ذَهَبٍ قَالَ ‏ ‏قُرْطَانِ ‏ ‏مِنْ نَارٍ قَالَ وَكَانَ عَلَيْهَا سِوَارٌ مِنْ ذَهَبٍ فَرَمَتْ بِهِ ثُمَّ قَالَتْ يَا رَسُولَ اللَّهِ إِنَّ إِحْدَانَا إِذَا لَمْ تَزَّيَّنْ لِزَوْجِهَا ‏ ‏صَلِفَتْ ‏ ‏عِنْدَهُ قَالَ فَقَالَ مَا يَمْنَعُ إِحْدَاكُنَّ تَصْنَعُ ‏ ‏قُرْطَيْنِ ‏ ‏مِنْ فِضَّةٍ ثُمَّ تُصَفِّرُهُمَا ‏ ‏بِالزَّعْفَرَانِ ‏","","",""],[9301,9301,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ أَنْزَلَ الْقُرْآنَ عَلَى سَبْعَةِ ‏ ‏أَحْرُفٍ ‏ ‏عَلِيمٌ حَكِيمٌ غَفُورٌ رَحِيمٌ ‏","","",""],[9302,9302,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ الْحَفَرِيُّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَفْسُ الْمُؤْمِنِ ‏ ‏مُعَلَّقَةٌ ‏ ‏مَا كَانَ عَلَيْهِ دَيْنٌ ‏","","",""],[9303,9303,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ الْحَفَرِيُّ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صِنْفَانِ مِنْ أُمَّتِي مِنْ أَهْلِ النَّارِ لَمْ أَرَهُمْ بَعْدُ نِسَاءٌ كَاسِيَاتٌ عَارِيَاتٌ ‏ ‏مَائِلَاتٌ ‏ ‏مُمِيلَاتٌ ‏ ‏عَلَى رُءُوسِهِنَّ أَمْثَالُ ‏ ‏أَسْنِمَةِ ‏ ‏الْإِبِلِ لَا يَدْخُلْنَ الْجَنَّةَ وَلَا يَجِدْنَ رِيحَهَا وَرِجَالٌ مَعَهُمْ ‏ ‏أَسْيَاطٌ ‏ ‏كَأَذْنَابِ ‏ ‏الْبَقَرِ يَضْرِبُونَ بِهَا النَّاسَ ‏","","",""],[9304,9304,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏التَّسْبِيحُ لِلرِّجَالِ وَالتَّصْفِيقُ لِلنِّسَاءِ ‏","","",""],[9305,9305,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعَلِّمُنَا أَنْ ‏ ‏لَا نُبَادِرَ الْإِمَامَ بِالرُّكُوعِ وَالسُّجُودِ وَإِذَا كَبَّرَ فَكَبِّرُوا وَإِذَا سَجَدَ فَاسْجُدُوا وَإِذَا قَالَ ‏ { ‏غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ ‏} ‏فَقُولُوا آمِينَ فَإِذَا وَافَقَ كَلَامَ الْمَلَائِكَةِ غُفِرَ لِمَنْ فِي الْمَسْجِدِ وَإِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقُولُوا رَبَّنَا لَكَ الْحَمْدُ ‏","","",""],[9306,9306,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏وَمُحَمَّدٌ ‏ ‏ابْنَا ‏ ‏عُبَيْدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ الْحَكَمِ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏شَيْخٍ ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏بَدَا ‏ ‏جَفَا ‏ ‏وَمَنْ تَبِعَ الصَّيْدَ غَفَلَ وَمَنْ أَتَى أَبْوَابَ السُّلْطَانِ ‏ ‏افْتُتِنَ ‏ ‏وَمَا ازْدَادَ عَبْدٌ مِنْ ‏ ‏السُّلْطَانِ قُرْبًا إِلَّا ازْدَادَ مِنْ اللَّهِ عَزَّ وَجَلَّ بُعْدًا ‏","","",""],[9307,9307,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏دَاوُدُ الْأَوْدِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي قَوْلِهِ ‏ { ‏عَسَى أَنْ يَبْعَثَكَ رَبُّكَ مَقَامًا مَحْمُودًا ‏} ‏قَالَ هُوَ الْمَقَامُ الَّذِي أَشْفَعُ لِأُمَّتِي فِيهِ ‏","","",""],[9308,9308,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ الْأَحْمَرُ ‏ ‏عَنْ ‏ ‏أُسَامَةَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَمْ مِنْ صَائِمٍ لَيْسَ لَهُ مِنْ صِيَامِهِ إِلَّا الْجُوعُ وَكَمْ مِنْ قَائِمٍ لَيْسَ لَهُ مِنْ قِيَامِهِ إِلَّا السَّهَرُ ‏","","",""],[9309,9309,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ يَعْنِي ابْنَ كَيْسَانَ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى قَبْرٍ فَقَالَ ائْتُونِي ‏ ‏بِجَرِيدَتَيْنِ ‏ ‏فَجَعَلَ إِحْدَاهُمَا عِنْدَ رَأْسِهِ وَالْأُخْرَى عِنْدَ رِجْلَيْهِ فَقِيلَ يَا نَبِيَّ اللَّهِ أَيَنْفَعُهُ ذَلِكَ قَالَ ‏ ‏لَنْ يَزَالَ أَنْ يُخَفَّفَ عَنْهُ بَعْضُ عَذَابِ الْقَبْرِ مَا كَانَ فِيهِمَا ‏ ‏نُدُوٌّ ‏","","",""],[9310,9310,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِعَمِّهِ ‏ ‏قُلْ لَا إِلَهَ إِلَّا اللَّهُ أَشْهَدْ لَكَ بِهَا عِنْدَ اللَّهِ يَوْمَ الْقِيَامَةِ قَالَ لَوْلَا أَنْ تُعَيِّرَنِي ‏ ‏قُرَيْشٌ ‏ ‏لَأَقْرَرْتُ عَيْنَكَ بِهَا قَالَ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏إِنَّكَ لَا تَهْدِي مَنْ أَحْبَبْتَ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَ ‏}","","",""],[9311,9311,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ الطَّنَافِسِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ كَيْسَانَ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏زَارَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَبْرَ أُمِّهِ فَبَكَى وَبَكَى مَنْ حَوْلَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَأْذَنْتُ رَبِّي فِي أَنْ أَسْتَغْفِرَ لَهَا فَلَمْ يُؤْذَنْ لِي وَاسْتَأْذَنْتُهُ فِي أَنْ أَزُورَ قَبْرَهَا فَأَذِنَ لِي ‏ ‏فَزُورُوا الْقُبُورَ فَإِنَّهَا تُذَكِّرُ الْمَوْتَ ‏","","",""],[9312,9312,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏جَاءَتْ امْرَأَةٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِهَا ‏ ‏لَمَمٌ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ ادْعُ اللَّهَ أَنْ يَشْفِيَنِي قَالَ ‏ ‏إِنْ شِئْتِ دَعَوْتُ اللَّهَ أَنْ يَشْفِيَكِ وَإِنْ شِئْتِ فَاصْبِرِي وَلَا حِسَابَ عَلَيْكِ قَالَتْ بَلْ أَصْبِرُ وَلَا حِسَابَ عَلَيَّ ‏","","",""],[9313,9313,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثِنْتَانِ هُمَا بِالنَّاسِ كُفْرٌ ‏ ‏نِيَاحَةٌ ‏ ‏عَلَى الْمَيِّتِ ‏ ‏وَطَعْنٌ ‏ ‏فِي النَّسَبِ ‏","","",""],[9314,9314,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏الْأَعْمَشُ ‏ ‏لَا أُرَاهُ إِلَّا قَدْ رَفَعَهُ قَالَ ‏ ‏وَيْلٌ ‏ ‏لِلْعَرَبِ ‏ ‏مِنْ أَمْرٍ قَدْ اقْتَرَبَ أَفْلَحَ مَنْ كَفَّ يَدَهُ ‏ ‏وَوَافَقَهُ ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏","","",""],[9315,9315,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا مَثَلُ هَؤُلَاءِ الصَّلَوَاتِ الْخَمْسِ مَثَلُ نَهْرٍ جَارٍ عَلَى بَابِ أَحَدِكُمْ يَغْتَسِلُ مِنْهُ كُلَّ يَوْمٍ خَمْسَ مَرَّاتٍ فَمَاذَا يُبْقِينَ مِنْ ‏ ‏دَرَنِهِ ‏","","",""],[9316,9316,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ أَبِي يَزِيدَ ‏ ‏عَنْ ‏ ‏حُصَيْنِ بْنِ اللَّجْلَاجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَجْتَمِعُ ‏ ‏الشُّحُّ ‏ ‏وَالْإِيمَانُ فِي جَوْفِ رَجُلٍ مُسْلِمٍ وَلَا يَجْتَمِعُ غُبَارٌ فِي سَبِيلِ اللَّهِ وَدُخَانُ جَهَنَّمَ فِي جَوْفِ رَجُلٍ مُسْلِمٍ ‏","","",""],[9317,9317,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏وَيَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ ‏ ‏إِنَّا نَجِدُ فِي أَنْفُسِنَا مَا يَسُرُّنَا نَتَكَلَّمُ بِهِ وَإِنَّ لَنَا مَا طَلَعَتْ عَلَيْهِ الشَّمْسُ قَالَ أَوَجَدْتُمْ ذَلِكَ قَالُوا نَعَمْ قَالَ ذَاكَ صَرِيحُ الْإِيمَانِ ‏","","",""],[9318,9318,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي مَالِكِ بْنِ ثَعْلَبَةَ بْنِ أَبِي مَالِكٍ الْقُرَظِيِّ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْحَكَمِ بْنِ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ مَا تَعُدُّونَ الشَّهِيدَ قَالُوا الَّذِي يُقَاتِلُ فِي سَبِيلِ اللَّهِ حَتَّى يُقْتَلَ قَالَ ‏ ‏إِنَّ الشَّهِيدَ فِي أُمَّتِي إِذًا لَقَلِيلٌ الْقَتِيلُ فِي سَبِيلِ اللَّهِ شَهِيدٌ وَالطَّعِينُ فِي سَبِيلِ اللَّهِ شَهِيدٌ وَالْغَرِيقُ فِي سَبِيلِ اللَّهِ شَهِيدٌ ‏ ‏وَالْخَارُّ ‏ ‏عَنْ دَابَّتِهِ فِي سَبِيلِ اللَّهِ شَهِيدٌ وَالْمَجْنُوبُ فِي سَبِيلِ اللَّهِ شَهِيدٌ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏الْمَجْنُوبُ صَاحِبُ الْجَنْبِ ‏","","",""],[9319,9319,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏دَاوُدُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ أَكْثَرَ مَا يُدْخِلُ النَّاسَ النَّارَ الْأَجْوَفَانِ قَالُوا يَا رَسُولَ اللَّهِ وَمَا الْأَجْوَفَانِ قَالَ الْفَرْجُ وَالْفَمُ قَالَ أَتَدْرُونَ أَكْثَرَ مَا يُدْخِلُ الْجَنَّةَ تَقْوَى اللَّهِ وَحُسْنُ الْخُلُقِ ‏","","",""],[9320,9320,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏دَاوُدُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَقُومَنَّ أَحَدُكُمْ إِلَى الصَّلَاةِ وَبِهِ أَذًى ‏ ‏يَعْنِي الْبَوْلَ وَالْغَائِطَ ‏","","",""],[9321,9321,"","","‏ ‏حَدَّثَنَا ‏ ‏تَلِيدُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الْحَجَّافِ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَظَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏عَلِيٍّ ‏ ‏وَالْحَسَنِ ‏ ‏وَالْحُسَيْنِ ‏ ‏وَفَاطِمَةَ ‏ ‏فَقَالَ أَنَا حَرْبٌ لِمَنْ حَارَبَكُمْ وَسِلْمٌ لِمَنْ سَالَمَكُمْ ‏","","",""],[9322,9322,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ إِدْرِيسَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سُهَيْلَ بْنَ أَبِي صَالِحٍ ‏ ‏يَذْكُرُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّيْتُمْ بَعْدَ الْجُمُعَةِ فَصَلُّوا أَرْبَعًا فَإِنْ ‏ ‏عَجِلَ ‏ ‏بِكَ شَيْءٌ فَصَلِّ رَكْعَتَيْنِ وَرَكْعَتَيْنِ إِذَا رَجَعْتَ ‏ ‏قَالَ ‏ ‏ابْنُ إِدْرِيسَ ‏ ‏وَلَا أَدْرِي هَذَا مِنْ حَدِيثِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمْ لَا ‏","","",""],[9323,9323,"","","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ الْفَزَارِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْضَلُ الْإِيمَانِ عِنْدَ اللَّهِ عَزَّ وَجَلَّ إِيمَانٌ لَا شَكَّ فِيهِ ‏ ‏وَغَزْوٌ ‏ ‏لَا ‏ ‏غُلُولَ ‏ ‏فِيهِ وَحَجٌّ ‏ ‏مَبْرُورٌ ‏ ‏قَالَ ‏ ‏فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏حَجٌّ ‏ ‏مَبْرُورٌ ‏ ‏يُكَفِّرُ خَطَايَا تِلْكَ السَّنَةِ ‏ ‏قَالَ ‏ ‏مَرْوَانُ ‏ ‏لَا شَكَّ فِيهِ عَنْ ‏ ‏الْحَجَّاجِ الصَّوَّافِ ‏ ‏أَوْ عَنْ ‏ ‏هِشَامٍ ‏","","",""],[9324,9324,"","","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ الْفَزَارِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏صَبِيحٌ أَبُو الْمَلِيحِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا صَالِحٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَا يَسْأَلْهُ يَغْضَبْ عَلَيْهِ ‏","","",""],[9325,9325,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمَّارُ بْنُ مُحَمَّدٍ ‏ ‏وَهُوَ ابْنُ أُخْتِ ‏ ‏سُفْيَانَ الثَّوْرِيِّ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُنْزَعُ الرَّحْمَةُ إِلَّا مِنْ شَقِيٍّ ‏","","",""],[9326,9326,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمَّارُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ يَعْنِي ابْنَ السَّائِبِ ‏ ‏عَنِ ‏ ‏الْأَغَرِّ أَبِي مُسْلِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ اللَّهُ عَزَّ وَجَلَّ ‏ ‏الْكِبْرِيَاءُ رِدَائِي وَالْعَظَمَةُ ‏ ‏إِزَارِي ‏ ‏فَمَنْ نَازَعَنِي شَيْئًا مِنْهُمَا أَلْقَيْتُهُ فِي جَهَنَّمَ ‏","","",""],[9327,9327,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمَّارُ بْنُ مُحَمَّدٍ ‏ ‏عَنِ ‏ ‏الصَّلْتِ بْنِ قُوَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ خَلِيلِي ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى لَا تَنْطَحَ ذَاتُ قَرْنٍ ‏ ‏جَمَّاءَ ‏","","",""],[9328,9328,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُوتِيتُ ‏ ‏جَوَامِعَ ‏ ‏الْكَلِمِ وَجُعِلَتْ لِي الْأَرْضُ مَسْجِدًا وَطَهُورًا ‏","","",""],[9329,9329,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حَبِيبٍ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُطَوِّسِ ‏ ‏عَنِ ‏ ‏الْمُطَوِّسِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَفْطَرَ يَوْمًا مِنْ رَمَضَانَ مِنْ غَيْرِ رُخْصَةٍ لَمْ يَجْزِهِ صِيَامُ الدَّهْرِ ‏","","",""],[9330,9330,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الْعُمَيْسِ عُتْبَةُ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ يَعْقُوبَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ النِّصْفُ مِنْ شَعْبَانَ فَأَمْسِكُوا عَنْ الصَّوْمِ حَتَّى يَكُونَ رَمَضَانُ ‏","","",""],[9331,9331,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِيسَى بْنُ الْمُسَيِّبِ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْهِرُّ ‏ ‏سَبُعٌ ‏","","",""],[9332,9332,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَا تَدْخُلُونَ الْجَنَّةَ حَتَّى تُؤْمِنُوا وَلَا تُؤْمِنُونَ حَتَّى تَحَابُّوا ثُمَّ قَالَ هَلْ أَدُلُّكُمْ عَلَى شَيْءٍ إِذَا فَعَلْتُمُوهُ تَحَابَبْتُمْ أَفْشُوا السَّلَامَ بَيْنَكُمْ ‏","","",""],[9333,9333,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْحَيَاءُ شُعْبَةٌ مِنْ الْإِيمَانِ ‏","","",""],[9334,9334,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَؤُمُّنَا فَيَجْهَرُ وَيُخَافِتُ فَجَهَرْنَا فِيمَا جَهَرَ وَخَافَتْنَا فِيمَا خَافَتَ وَسَمِعْتُهُ يَقُولُ لَا صَلَاةَ إِلَّا بِقِرَاءَةٍ ‏","","",""],[9335,9335,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏خَالِهِ ‏ ‏الْحَارِثِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَجَدَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالْمُسْلِمُونَ فِي ‏ ‏النَّجْمِ ‏ ‏إِلَّا رَجُلَيْنِ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏أَرَادَا بِذَلِكَ الشُّهْرَةَ ‏","","",""],[9336,9336,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَيَعْلَى ‏ ‏وَمُحَمَّدٌ ‏ ‏ابْنَا ‏ ‏عُبَيْدٍ ‏ ‏قَالُوا أَخْبَرَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَرَأَ ابْنُ ‏ ‏آدَمَ ‏ ‏السَّجْدَةَ ‏ ‏اعْتَزَلَ الشَّيْطَانُ يَبْكِي يَقُولُ يَا وَيْلَهُ أُمِرَ بِالسُّجُودِ فَسَجَدَ فَلَهُ الْجَنَّةُ وَأُمِرْتُ بِالسُّجُودِ فَعَصَيْتُ فَلِي النَّارُ ‏","","",""],[9337,9337,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ عَمَلِ ابْنِ ‏ ‏آدَمَ ‏ ‏يُضَاعَفُ الْحَسَنَةُ عَشْرُ أَمْثَالِهَا إِلَى سَبْعِ مِائَةِ ضِعْفٍ إِلَى مَا شَاءَ اللَّهُ قَالَ اللَّهُ عَزَّ وَجَلَّ إِلَّا الصَّوْمَ فَإِنَّهُ لِي وَأَنَا ‏ ‏أَجْزِي ‏ ‏بِهِ يَدَعُ طَعَامَهُ وَشَهْوَتَهُ مِنْ أَجْلِي لِلصَّائِمِ فَرْحَتَانِ فَرْحَةٌ عِنْدَ فِطْرِهِ وَفَرْحَةٌ عِنْدَ لِقَاءِ رَبِّهِ ‏ ‏وَلَخُلُوفُ ‏ ‏فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ ‏ ‏الْمِسْكِ ‏ ‏الصَّوْمُ ‏ ‏جُنَّةٌ ‏ ‏الصَّوْمُ ‏ ‏جُنَّةٌ ‏","","",""],[9338,9338,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي رَزِينٍ ‏ ‏وَأَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏وَالْأَعْمَشُ ‏ ‏يَرْفَعُهُ ‏ ‏إِذَا انْقَطَعَ ‏ ‏شِسْعُ ‏ ‏أَحَدِكُمْ فَلَا ‏ ‏يَمْشِي فِي النَّعْلِ الْوَاحِدَةِ ‏","","",""],[9339,9339,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏النَّهَّاسُ بْنُ قَهْمٍ الصُّبَحِيُّ ‏ ‏عَنْ ‏ ‏شَدَّادٍ أَبِي عَمَّارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ حَافَظَ عَلَى ‏ ‏شُفْعَةِ ‏ ‏الضُّحَى غُفِرَتْ لَهُ ذُنُوبُهُ وَإِنْ كَانَتْ مِثْلَ ‏ ‏زَبَدِ ‏ ‏الْبَحْرِ ‏","","",""],[9340,9340,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَلِيلُ بْنُ مُرَّةَ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ قُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَمْ ‏ ‏يُوتِرْ ‏ ‏فَلَيْسَ مِنَّا ‏","","",""],[9341,9341,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ بُرْقَانَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْأَصَمِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ الْغِنَى عَنْ كَثْرَةِ ‏ ‏الْعَرَضِ ‏ ‏إِنَّمَا الْغِنَى غِنَى النَّفْسِ ‏","","",""],[9342,9342,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مَلِيحٍ الْمَدَنِيُّ ‏ ‏سَمِعَهُ مِنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَمْ يَدْعُ اللَّهَ غَضِبَ اللَّهُ عَلَيْهِ ‏","","",""],[9343,9343,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَلْبُ الشَّيْخِ شَابٌّ عَلَى حُبِّ اثْنَتَيْنِ عَلَى جَمْعِ الْمَالِ وَطُولِ الْحَيَاةِ ‏","","",""],[9344,9344,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ الْفَضْلِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا وَقَعَ الذُّبَابُ فِي طَعَامِ أَحَدِكُمْ أَوْ شَرَابِهِ فَلْيَغْمِسْهُ إِذَا أَخْرَجَهُ فَإِنَّ فِي أَحَدِ جَنَاحَيْهِ دَاءً وَفِي الْآخَرِ شِفَاءً وَإِنَّهُ يُقَدِّمُ الدَّاءَ ‏","","",""],[9345,9345,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏النَّهَّاسُ ‏ ‏عَنْ ‏ ‏شَيْخٍ ‏ ‏بِمَكَّةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏فِرَّ مِنْ ‏ ‏الْمَجْذُومِ ‏ ‏فِرَارَكَ مِنْ الْأَسَدِ ‏","","",""],[9346,9346,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏بَعْجَةَ بْنِ عَبْدِ اللَّهِ الْجُهَنِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيَأْتِيَنَّ عَلَى النَّاسِ زَمَانٌ يَكُونُ أَفْضَلُ النَّاسِ فِيهِ بِمَنْزِلَةِ رَجُلٍ أَخَذَ ‏ ‏بِعِنَانِ ‏ ‏فَرَسِهِ فِي سَبِيلِ اللَّهِ كُلَّمَا سَمِعَ بِهَيْعَةٍ ‏ ‏اسْتَوَى ‏ ‏عَلَى ‏ ‏مَتْنِهِ ‏ ‏ثُمَّ طَلَبَ الْمَوْتَ ‏ ‏مَظَانَّهُ ‏ ‏وَرَجُلٌ فِي ‏ ‏شِعْبٍ ‏ ‏مِنْ هَذِهِ ‏ ‏الشِّعَابِ ‏ ‏يُقِيمُ الصَّلَاةَ ‏ ‏وَيُؤْتِي الزَّكَاةَ وَيَدَعُ النَّاسَ إِلَّا مِنْ خَيْرٍ ‏","","",""],[9347,9347,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُرِيدُ سَفَرًا فَقَالَ يَا رَسُولَ اللَّهِ أَوْصِنِي قَالَ ‏ ‏أُوصِيكَ بِتَقْوَى اللَّهِ وَالتَّكْبِيرِ عَلَى كُلِّ ‏ ‏شَرَفٍ ‏ ‏فَلَمَّا مَضَى قَالَ اللَّهُمَّ ‏ ‏ازْوِ ‏ ‏لَهُ الْأَرْضَ وَهَوِّنْ عَلَيْهِ السَّفَرَ ‏","","",""],[9348,9348,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعْدَانُ الْجُهَنِيُّ ‏ ‏عَنْ ‏ ‏سَعْدٍ أَبِي مُجَاهِدٍ الطَّائِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مُدِلَّةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْإِمَامُ الْعَادِلُ لَا تُرَدُّ دَعْوَتُهُ ‏","","",""],[9349,9349,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَأَبُو نُعَيْمٍ وَهُوَ الْفَضْلُ بْنُ دُكَيْنٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا لَقِيتُمْ ‏ ‏الْيَهُودَ ‏ ‏فِي الطَّرِيقِ فَاضْطَرُّوهُمْ إِلَى أَضْيَقِهَا وَلَا تَبْدَءُوهُمْ بِالسَّلَامِ ‏ ‏قَالَ ‏ ‏أَبُو نُعَيْمٍ ‏ ‏الْمُشْرِكِينَ بِالطَّرِيقِ ‏","","",""],[9350,9350,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عُبَيْدٍ ‏ ‏مَوْلَى ‏ ‏أَبِي رُهْمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّمَا امْرَأَةٍ تَطَيَّبَتْ ثُمَّ خَرَجَتْ إِلَى الْمَسْجِدِ لِيُوجَدَ رِيحُهَا لَمْ يُقْبَلْ مِنْهَا صَلَاةٌ حَتَّى تَغْتَسِلَ اغْتِسَالَهَا مِنْ الْجَنَابَةِ ‏","","",""],[9351,9351,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏الْمَعْنَى ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى ‏ ‏الْحَسَنَ بْنَ عَلِيٍّ ‏ ‏أَخَذَ تَمْرَةً مِنْ تَمْرِ ‏ ‏الصَّدَقَةِ ‏ ‏فَلَاكَهَا فِي ‏ ‏فِيهِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كِخْ كِخْ فَإِنَّا لَا تَحِلُّ لَنَا ‏ ‏الصَّدَقَةُ ‏","","",""],[9352,9352,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَقُلْ أَحَدُكُمْ لِعَبْدِهِ عَبْدِي وَلَكِنْ لِيَقُلْ فَتَايَ وَلَا يَقُلْ الْعَبْدُ لِسَيِّدِهِ رَبِّي وَلَكِنْ لِيَقُلْ سَيِّدِي ‏","","",""],[9353,9353,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏مَوْلَى ‏ ‏التَّوْأَمَةِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَلَّى عَلَى جَنَازَةٍ فِي الْمَسْجِدِ فَلَيْسَ لَهُ شَيْءٌ ‏","","",""],[9354,9354,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏وَهْبِ بْنِ كَيْسَانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي جَنَازَةٍ فَرَأَى ‏ ‏عُمَرُ ‏ ‏امْرَأَةً فَصَاحَ بِهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعْهَا يَا ‏ ‏عُمَرُ ‏ ‏فَإِنَّ الْعَيْنَ دَامِعَةٌ وَالنَّفْسَ مُصَابَةٌ وَالْعَهْدَ حَدِيثٌ ‏","","",""],[9355,9355,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَأَنْ يَجْلِسَ أَحَدُكُمْ عَلَى جَمْرَةٍ حَتَّى تَحْتَرِقَ ثِيَابُهُ خَيْرٌ لَهُ مِنْ أَنْ يَجْلِسَ عَلَى قَبْرٍ ‏","","",""],[9356,9356,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ مَخْلَدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَلْعُونٌ مَنْ ‏ ‏أَتَى ‏ ‏امْرَأَتَهُ فِي ‏ ‏دُبُرِهَا ‏","","",""],[9357,9357,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَصُمْ الْمَرْأَةُ يَوْمًا وَاحِدًا وَزَوْجُهَا شَاهِدٌ إِلَّا بِإِذْنِهِ ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏إِلَّا رَمَضَانَ ‏","","",""],[9358,9358,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏دَاوُدُ الزَّعَافِرِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏عَسَى أَنْ يَبْعَثَكَ رَبُّكَ مَقَامًا مَحْمُودًا ‏} ‏قَالَ الشَّفَاعَةُ ‏","","",""],[9359,9359,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبَّادِ بْنِ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏جَاءَ مُشْرِكُو ‏ ‏قُرَيْشٍ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُخَاصِمُونَهُ فِي ‏ ‏الْقَدَرِ ‏ ‏فَنَزَلَتْ ‏ { ‏يَوْمَ يُسْحَبُونَ فِي النَّارِ عَلَى وُجُوهِهِمْ ذُوقُوا مَسَّ ‏ ‏سَقَرَ ‏ ‏إِنَّا كُلَّ شَيْءٍ خَلَقْنَاهُ بِقَدَرٍ ‏}","","",""],[9360,9360,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ عَلَى الْمِنْبَرِ ‏ ‏أَشْعَرُ ‏ ‏كَلِمَةٍ قَالَتْهَا ‏ ‏الْعَرَبُ ‏ ‏قَوْلُ ‏ ‏لَبِيدِ بْنِ رَبِيعَةَ ‏ ‏أَلَا كُلُّ شَيْءٍ مَا ‏ ‏خَلَا ‏ ‏اللَّهَ بَاطِلُ ‏","","",""],[9361,9361,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَصْحَبُ الْمَلَائِكَةُ رُفْقَةً فِيهَا كَلْبٌ وَلَا جَرَسٌ ‏","","",""],[9362,9362,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُثْمَانُ بْنُ وَاقِدٍ يَعْنِي الْعُمَرِيَّ ‏ ‏عَنْ ‏ ‏كِدَامِ بْنِ عَبْدِ الرَّحْمَنِ السُّلَمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي كِبَاشٍ ‏ ‏قَالَ ‏ ‏جَلَبْتُ غَنَمًا ‏ ‏جُذْعَانًا إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَكَسَدَتْ عَلَيَّ فَلَقِيتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏فَسَأَلْتُهُ فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ نِعْمَ ‏ ‏أَوْ ‏ ‏نِعْمَتِ ‏ ‏الْأُضْحِيَّةُ ‏ ‏الْجَذَعُ ‏ ‏مِنْ الضَّأْنِ فَانْتَهَبَهَا النَّاسُ ‏","","",""],[9363,9363,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏السَّفَرُ قِطْعَةٌ مِنْ الْعَذَابِ يَمْنَعُ أَحَدَكُمْ نَوْمَهُ وَطَعَامَهُ فَإِذَا ‏ ‏قَضَى ‏ ‏أَحَدُكُمْ ‏ ‏نَهْمَتَهُ ‏ ‏مِنْ سَفَرِهِ فَلْيُعَجِّلْ إِلَى أَهْلِهِ ‏","","",""],[9364,9364,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُسَافِرْ امْرَأَةٌ مَسِيرَةَ يَوْمٍ تَامٍّ إِلَّا مَعَ ذِي ‏ ‏مَحْرَمٍ ‏","","",""],[9365,9365,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏السُّدِّيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏يَرْفَعُهُ ‏ ‏قَالَ ‏ ‏إِنَّ الْمَيِّتَ لَيَسْمَعُ ‏ ‏خَفْقَ ‏ ‏نِعَالِهِمْ إِذَا وَلَّوْا ‏ ‏مُدْبِرِينَ ‏","","",""],[9366,9366,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعْدَانُ الْجُهَنِيُّ ‏ ‏عَنْ ‏ ‏أَبِي مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أَبِي مُدِلَّةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثَةٌ لَا يُرَدُّ دُعَاؤُهُمْ الْإِمَامُ الْعَادِلُ وَالصَّائِمُ حَتَّى يُفْطِرَ وَدَعْوَةُ الْمَظْلُومِ يَرْفَعُهَا اللَّهُ فَوْقَ الْغَمَامِ يَوْمَ الْقِيَامَةِ وَيَفْتَحُ لَهَا أَبْوَابَ السَّمَاءِ وَيَقُولُ الرَّبُّ عَزَّ وَجَلَّ بِعِزَّتِي لَأَنْصُرَنَّكِ وَلَوْ بَعْدَ حِينٍ ‏","","",""],[9367,9367,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعْدَانُ الْجُهَنِيُّ ‏ ‏عَنْ ‏ ‏أَبِي مُجَاهِدٍ الطَّائِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مُدِلَّةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قُلْنَا يَا رَسُولَ اللَّهِ أَخْبِرْنَا عَنْ الْجَنَّةِ مَا بِنَاؤُهَا قَالَ ‏ ‏لَبِنَةٌ ‏ ‏مِنْ ذَهَبٍ ‏ ‏وَلَبِنَةٌ ‏ ‏مِنْ فِضَّةٍ ‏ ‏مِلَاطُهَا ‏ ‏الْمِسْكُ ‏ ‏الْأَذْفَرُ ‏ ‏حَصْبَاؤُهَا الْيَاقُوتُ وَاللُّؤْلُؤُ وَتُرْبَتُهَا ‏ ‏الْوَرْسُ ‏ ‏وَالزَّعْفَرَانُ مَنْ يَدْخُلُهَا يَخْلُدُ لَا يَمُوتُ وَيَنْعَمُ لَا يَبْأَسُ لَا يَبْلَى شَبَابُهُمْ وَلَا تُخَرَّقُ ثِيَابُهُمْ ‏","","",""],[9368,9368,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏يَجْزِي وَلَدٌ وَالِدَهُ إِلَّا أَنْ يَجِدَهُ مَمْلُوكًا فَيَشْتَرِيَهُ فَيُعْتِقَهُ ‏","","",""],[9369,9369,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يُونُسُ يَعْنِي ابْنَ أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَازَالَ ‏ ‏جِبْرِيلُ ‏ ‏يُوصِينِي بِالْجَارِ حَتَّى ظَنَنْتُ أَنَّهُ سَيُوَرِّثُهُ ‏","","",""],[9370,9370,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ الْمِسْكِينُ الطَّوَّافَ عَلَيْكُمْ الَّذِي تَرُدُّهُ اللُّقْمَةُ وَاللُّقْمَتَانِ وَلَكِنَّ الْمِسْكِينَ ‏ ‏الْمُتَعَفِّفُ ‏","","",""],[9371,9371,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْإِيمَانُ بِضْعٌ وَسَبْعُونَ بَابًا ‏ ‏فَأَدْنَاهُ ‏ ‏إِمَاطَةُ ‏ ‏الْأَذَى عَنْ الطَّرِيقِ وَأَرْفَعُهَا قَوْلُ لَا إِلَهَ إِلَّا اللَّهُ ‏","","",""],[9372,9372,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ بُرْقَانَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْأَصَمِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْإِيمَانُ بِضْعٌ وَسَبْعُونَ بَابًا ‏ ‏فَأَدْنَاهَا ‏ ‏إِمَاطَةُ ‏ ‏الْأَذَى عَنْ الطَّرِيقِ وَأَرْفَعُهَا قَوْلُ لَا إِلَهَ إِلَّا اللَّهُ ‏","","",""],[9373,9373,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ بُرْقَانَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْأَصَمِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ ‏ ‏أَنَا عِنْدَ ظَنِّ عَبْدِي بِي وَأَنَا مَعَهُ إِذَا دَعَانِي ‏","","",""],[9374,9374,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏عَنْ ‏ ‏أَبِي كَثِيرٍ الْحَنَفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الزَّبِيبِ وَالتَّمْرِ ‏ ‏وَالْبُسْرِ ‏ ‏وَالتَّمْرِ وَقَالَ ‏ ‏يُنْبَذُ ‏ ‏كُلُّ وَاحِدٍ مِنْهُمَا عَلَى حِدَةٍ ‏","","",""],[9375,9375,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبَانُ بْنُ صَمْعَةَ ‏ ‏عَنْ ‏ ‏زُبَيْبَةِ ابْنَةِ النُّعْمَانِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْأَوْعِيَةِ إِلَّا وِعَاءً ‏ ‏يُوكَأُ ‏ ‏رَأْسُهُ ‏","","",""],[9376,9376,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏فُضَيْلُ بْنُ غَزْوَانَ الضَّبِّيُّ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثٌ إِذَا خَرَجْنَ لَمْ يَنْفَعْ نَفْسًا إِيمَانُهَا لَمْ تَكُنْ آمَنَتْ مِنْ قَبْلُ أَوْ كَسَبَتْ فِي إِيمَانِهَا خَيْرًا ‏ ‏طُلُوعُ الشَّمْسِ مِنْ مَغْرِبِهَا وَالدُّخَانُ وَدَابَّةُ الْأَرْضِ ‏","","",""],[9377,9377,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ الْقَعْقَاعِ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ اجْعَلْ رِزْقَ آلِ ‏ ‏مُحَمَّدٍ ‏ ‏قُوتًا ‏","","",""],[9378,9378,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَحَبَّ أَنْ يَقْرَأَ الْقُرْآنَ غَرِيضًا كَذَا قَالَ كَمَا أُنْزِلَ فَلْيَقْرَأْهُ عَلَى قِرَاءَةِ ‏ ‏ابْنِ أُمِّ عَبْدٍ ‏","","",""],[9379,9379,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ أَحَقُّ بِمَجْلِسِهِ إِذَا رَجَعَ إِلَيْهِ ‏","","",""],[9380,9380,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الدَّوَاءِ ‏ ‏الْخَبِيثِ ‏ ‏يَعْنِي السُّمَّ ‏","","",""],[9381,9381,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ ثُوَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏دَخَلَ عَلَيَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا ‏ ‏أَشْتَكِي ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏فِي حَدِيثِهِ ‏ ‏يَعُودُنِي ‏ ‏فَقَالَ أَلَا أُعَلِّمُكَ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏أَلَا ‏ ‏أَرْقِيكَ ‏ ‏بِرُقْيَةٍ ‏ ‏رَقَانِي ‏ ‏بِهَا ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏قُلْتُ بَلَى بِأَبِي وَأُمِّي قَالَ ‏ ‏بِسْمِ اللَّهِ ‏ ‏أَرْقِيكَ ‏ ‏وَاللَّهُ ‏ ‏يَشْفِيكَ مِنْ كُلِّ دَاءٍ يُؤْذِيكَ وَمِنْ شَرِّ ‏ ‏النَّفَّاثَاتِ ‏ ‏فِي الْعُقَدِ وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ ‏ ‏وَقَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏مِنْ كُلِّ دَاءٍ فِيكَ ‏","","",""],[9382,9382,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ كُلَيْبٍ الْجَرْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏مَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى الضُّحَى قَطُّ إِلَّا مَرَّةً ‏","","",""],[9383,9383,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي الْجَحَّافِ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ إِنِّي أُحِبُّهُمَا فَأَحِبَّهُمَا ‏","","",""],[9384,9384,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَوْشَبُ بْنُ عَقِيلٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَهْدِيٌّ الْعَبْدِيُّ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏قَالَ قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏فِي بَيْتِهِ فَسَأَلْتُهُ عَنْ صَوْمِ ‏ ‏عَرَفَةَ ‏ ‏بِعَرَفَاتٍ ‏ ‏فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَوْمِ ‏ ‏عَرَفَةَ ‏ ‏بِعَرَفَاتٍ ‏","","",""],[9385,9385,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏هَارُونَ الثَّقَفِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَطَاءً ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏فِي كُلِّ صَلَاةٍ قِرَاءَةٌ ‏ ‏فَمَا أَسْمَعَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْمَعْنَاكُمْ وَمَا لَمْ يُسْمِعْنَا لَمْ نُسْمِعْكُمْ ‏","","",""],[9386,9386,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي هِلَالٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذُبَابٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَجُلًا مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ ‏ ‏بِشِعْبٍ ‏ ‏فِيهِ عَيْنٌ عَذْبَةٌ قَالَ فَأَعْجَبَتْهُ ‏ ‏يَعْنِي طِيبَ ‏ ‏الشِّعْبِ ‏ ‏فَقَالَ لَوْ أَقَمْتُ هَاهُنَا وَخَلَوْتُ ثُمَّ قَالَ لَا حَتَّى أَسْأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَهُ فَقَالَ ‏ ‏مُقَامُ أَحَدِكُمْ ‏ ‏يَعْنِي فِي سَبِيلِ اللَّهِ خَيْرٌ مِنْ عِبَادَةِ أَحَدِكُمْ فِي أَهْلِهِ سِتِّينَ سَنَةً أَمَا تُحِبُّونَ أَنْ يَغْفِرَ اللَّهُ لَكُمْ وَتَدْخُلُونَ الْجَنَّةَ جَاهِدُوا فِي سَبِيلِ اللَّهِ مَنْ قَاتَلَ فِي سَبِيلِ اللَّهِ ‏ ‏فُوَاقَ ‏ ‏نَاقَةٍ وَجَبَتْ لَهُ الْجَنَّةُ ‏","","",""],[9387,9387,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُونُوا عِبَادَ اللَّهِ إِخْوَانًا لَا تَعَادَوْا وَلَا ‏ ‏تَبَاغَضُوا ‏ ‏سَدِّدُوا ‏ ‏وَقَارِبُوا ‏ ‏وَأَبْشِرُوا ‏","","",""],[9388,9388,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏يَعْنِي مَوْلَى ‏ ‏التَّوْأَمَةِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا اجْتَمَعَ قَوْمٌ فِي مَجْلِسٍ فَتَفَرَّقُوا وَلَمْ يَذْكُرُوا اللَّهَ عَزَّ وَجَلَّ وَيُصَلُّوا عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا كَانَ مَجْلِسُهُمْ ‏ ‏تِرَةً ‏ ‏عَلَيْهِمْ يَوْمَ الْقِيَامَةِ ‏","","",""],[9389,9389,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏مَوْلَى ‏ ‏التَّوْأَمَةِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا حَجَّ بِنِسَائِهِ قَالَ ‏ ‏إِنَّمَا هِيَ هَذِهِ الْحَجَّةُ ثُمَّ الْزَمْنَ ‏ ‏ظُهُورَ الْحُصْرِ ‏","","",""],[9390,9390,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ شَرِيكٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَطَاءٌ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِعْمَ الْإِبِلُ الثَّلَاثُونَ يُحْمَلُ عَلَى ‏ ‏نَجِيبِهَا ‏ ‏وَتُعِيرُ ‏ ‏أَدَاتَهَا ‏ ‏وَتُمْنَحُ ‏ ‏غَزِيرَتُهَا ‏ ‏وَيُجْبِيهَا يَوْمَ ‏ ‏وِرْدِهَا ‏ ‏فِي ‏ ‏أَعْطَانِهَا ‏","","",""],[9391,9391,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏شَيْخٍ ‏ ‏سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْتِي عَلَى النَّاسِ زَمَانٌ يُخَيَّرُ الرَّجُلُ فِيهِ بَيْنَ الْعَجْزِ وَالْفُجُورِ فَلْيَخْتَرْ الْعَجْزَ عَلَى الْفُجُورِ ‏","","",""],[9392,9392,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ الْقَعْقَاعِ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ يَا رَسُولَ اللَّهِ ‏ ‏أَيُّ الصَّدَقَةِ أَفْضَلُ قَالَ أَنْ تَصَدَّقَ وَأَنْتَ شَحِيحٌ ‏ ‏أَوْ صَحِيحٌ ‏ ‏تَأْمُلُ الْعَيْشَ ‏ ‏وَتَخْشَى الْفَقْرَ وَلَا تُمْهِلْ حَتَّى إِذَا كَانَتْ بِالْحُلْقُومِ قُلْتَ لِفُلَانٍ كَذَا وَلِفُلَانٍ كَذَا وَقَدْ كَانَ ‏","","",""],[9393,9393,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَنْصُورُ بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ الْمَخْزُومِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَمْنَعَنَّ أَحَدُكُمْ جَارَهُ أَنْ يَضَعَ خَشَبَاتِهِ عَلَى جِدَارِهِ ‏","","",""],[9394,9394,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏أَفْلَحَ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ مُحَمَّدِ بْنِ عَمْرِو بْنِ حَزْمٍ ‏ ‏عَنْ ‏ ‏سَلْمَانَ الْأَغَرِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمَدِينَةُ ‏ ‏مَنْ صَبَرَ عَلَى ‏ ‏شِدَّتِهَا ‏ ‏وَلَأْوَائِهَا ‏ ‏كُنْتُ لَهُ شَفِيعًا ‏ ‏أَوْ شَهِيدًا ‏ ‏يَوْمَ الْقِيَامَةِ ‏","","",""],[9395,9395,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي مَيْمُونَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏جَاءَتْ امْرَأَةٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ طَلَّقَهَا زَوْجُهَا فَأَرَادَتْ أَنْ تَأْخُذَ وَلَدَهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَهِمَا ‏ ‏فِيهِ فَقَالَ الرَّجُلُ مَنْ ‏ ‏يَحُولُ ‏ ‏بَيْنِي وَبَيْنَ ابْنِي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلِابْنِ ‏ ‏اخْتَرْ أَيَّهُمَا شِئْتَ فَاخْتَارَ أُمَّهُ فَذَهَبَتْ بِهِ ‏","","",""],[9396,9396,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَغَرِّ أَبِي مُسْلِمٍ ‏ ‏قَالَ أَشْهَدُ عَلَى ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَأَبِي سَعِيدٍ ‏ ‏أَنَّهُمَا شَهِدَا لِي عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ وَأَنَا أَشْهَدُ عَلَيْهِمَا ‏ ‏مَا قَعَدَ قَوْمٌ يَذْكُرُونَ اللَّهَ إِلَّا حَفَّتْ بِهِمْ الْمَلَائِكَةُ وَتَنَزَّلَتْ عَلَيْهِمْ السَّكِينَةُ وَتَغَشَّتْهُمْ الرَّحْمَةُ وَذَكَرَهُمْ اللَّهُ فِيمَنْ عِنْدَهُ ‏","","",""],[9397,9397,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ يَعْنِي ابْنَ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أَبِي حَكِيمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ ابْنِ مَرْجَانَةَ ‏ ‏أَنَّهُ حَدَّثَ ‏ ‏عَلِيَّ بْنَ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَعْتَقَ رَقَبَةً كَانَ لَهُ بِعِتْقِ كُلِّ عُضْوٍ مِنْهُ عُضْوٌ مِنْ النَّارِ حَتَّى ذَكَرَ الْفَرْجَ ‏ ‏قَالَ ‏ ‏فَدَعَا ‏ ‏عَلِيُّ بْنُ حُسَيْنٍ ‏ ‏غُلَامًا لَهُ فَأَعْتَقَهُ ‏","","",""],[9398,9398,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَامَ الرَّجُلُ مِنْ مَجْلِسِهِ ثُمَّ رَجَعَ فَهُوَ أَحَقُّ بِهِ ‏","","",""],[9399,9399,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنِ ‏ ‏الطُّفَاوِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏يُبَاشِرُ ‏ ‏الرَّجُلُ الرَّجُلَ وَلَا الْمَرْأَةُ الْمَرْأَةَ إِلَّا الْوَلَدُ وَالْوَالِدَةُ ‏","","",""],[9400,9400,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ ذَكْوَانَ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَلْبُ الشَّيْخِ شَابٌّ عَلَى حُبِّ اثْنَتَيْنِ جَمْعِ الْمَالِ وَطُولِ الْحَيَاةِ ‏","","",""]];
